import { GameTask } from './GameTask';
import { GAMEVIEWMAP } from '../store/StoreMap';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/**
 * 恭喜獲得局數免費遊戲 轉場前的彈窗
 * 點畫面任何地方關閉彈窗
 * 呼叫 GameStore.completeWinFreeGame() 才繼續往下
 */
export class WinFreeGamePopupTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly freeRoundCount: number
    ) {
        super();
    }

    /** Task 進入點：跳出「獲得免費遊戲」彈窗，關掉後通知框架。 */
    protected onStart(): void {
        this.run()
            .catch((error) => console.warn('[WinFreeGamePopupTask] failed', error))
            .finally(() => this.finish());
    }

    /**
     * 顯示獲得免費遊戲的彈窗並等玩家關閉。
     *
     * @returns 彈窗關閉後 resolve。
     */
    private async run(): Promise<void> {
        const viewStore = this.game.storeManager.getViewStore();
        viewStore.setGameViewName(GAMEVIEWMAP.WINFREEGAMEPOPUP);
        await this.game.storeManager.getGameStore().playWinFreeGame(this.freeRoundCount);
        viewStore.setDeleteViewName('WinFreeGamePopup');
    }
}
