import { screen, Size, view, ResolutionPolicy } from "cc";
import {
    GAME_EVENT_ID,
    GAME_EVENT_TYPE,
    gameRuntimeEventBus,
} from "../events/GameRuntimeEventBus";

function getFrameSize(): Size {
    const dpr = screen.devicePixelRatio;
    const sizeInCssPixels = screen.windowSize;
    sizeInCssPixels.width /= dpr;
    sizeInCssPixels.height /= dpr;
    return sizeInCssPixels;
}

export class DeviceStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('DeviceStore') */
    public readonly $modelType = 'DeviceStore';

    private _orientation: "" | "portrait" | "landscape" = "";
    /**
     * 目前的螢幕方向。
     *
     * @returns 'portrait'、'landscape'，或還沒判定時的空字串。
     */
    get orientation(): "" | "portrait" | "landscape" { return this._orientation; }

    /** 保留建構子參數是為了相容 StoreManager 裡 `new DeviceStore({})` 的舊呼叫方式。
     *  原本的 onInit()（mobx-keystone Model 生命週期 hook，建構時就會觸發）直接搬進來。 */
    constructor(_props?: unknown) {
        this.checkOrientation();
        screen.on("window-resize", this.onResize);
    }

    /**
     * 設定螢幕方向並發 DEVICE_ORIENTATION_CHANGED；跟目前相同時直接略過。
     *
     * @param orientation 新的方向。
     */
    setOrientation(orientation: "" | "portrait" | "landscape"): void {
        if (this._orientation === orientation) return;
        this._orientation = orientation;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, {
            eventId: GAME_EVENT_ID.DEVICE_ORIENTATION_CHANGED,
            orientation,
        });
    }

    onResize = (): void => {
        this.checkOrientation();
    };

    /**
     * 量一次畫面尺寸並更新方向。
     *
     * 寬高差不到 50 時直接不動：接近正方形的視窗（桌機拖拉中、平板分割畫面）
     * 會讓判定在兩個方向之間來回跳，整套 UI 跟著反覆重排。
     */
    checkOrientation(): void {
        const frame = getFrameSize();
        // 寬高差太小時不切換，避免臨界值反覆跳
        if (Math.abs(frame.width - frame.height) < 50) return;
        const isLandscape = frame.width > frame.height;
        const next = isLandscape ? "landscape" : "portrait";
        if (next !== this._orientation) {
            console.log(`[DeviceStore] orientation: ${this._orientation} → ${next} (${frame.width.toFixed(0)}x${frame.height.toFixed(0)})`);
        }
        this.setOrientation(next);
        next == 'landscape' ?
            view.setDesignResolutionSize(1280, 720, ResolutionPolicy.FIXED_HEIGHT) :
            view.setDesignResolutionSize(720, 1280, ResolutionPolicy.FIXED_HEIGHT);
    }

    /**
     * 目前是不是橫版。
     *
     * @returns 橫版時 true。
     */
    get isLandscape(): boolean {
        return this._orientation === "landscape";
    }

    /**
     * 目前是不是直版。
     *
     * @returns 直版時 true。
     */
    get isPortrait(): boolean {
        return this._orientation === "portrait";
    }

    /**
     * 方向的單字母代碼，用來組 prefab／節點名稱。
     *
     * @returns 橫版 'h'，其餘 'v'。
     */
    get direction(): "h" | "v" {
        return this._orientation === "landscape" ? "h" : "v";
    }
}
