import GameConfigManager from '../../config/GameConfigManager';
import { createSlotGridLayout, getSlotLayoutSource } from '../GridLayoutConfig';

export type BetConfig = { min: string; max: string; defaultBet: string; levels: string[] };

export type SlotApiDebugResultControl = {
    symbol_control?: { symbol: number; count: number; line?: number };
    win?: { min: number; max: number };
    jackpot?: Partial<Record<'mini' | 'minor' | 'major' | 'grand', boolean>>;
    /**
     * 免費遊戲的驗證治具，**不是玩法設定**：加局（retrigger）自然發生率只有每局幾個百分點，
     * 手動玩幾乎碰不到，開這個才驗得到演出與局數顯示。目前只有 1003 的引擎會讀。
     */
    free_game?: {
        /**
         * 強制加局：`'first'` 只有第 1 局加（驗演出與局數跳號用，一次 FG 剛好看到一次）；
         * `'every'` 每局都加（壓力測試，會一路加到局數安全閥才停）。
         */
        retrigger?: 'first' | 'every';
        /** 加局時初盤要放幾顆 Scatter（決定加幾局）；不給就隨機 */
        retrigger_scatters?: number;
    };
};
export const getSlotApiDebugControl = (): SlotApiDebugResultControl | null => (globalThis as any).__slotApiDebugControl__ ?? null;

/**
 * 盤面形狀依當下的 GAMEID 取，不能在 module 載入時就算好——GAMEID 是進遊戲場景才寫入
 * globalThis 的，此檔被 import 的時機比那更早，先算會一律拿到預設的 1001 盤面。
 * 每次呼叫重建物件，切換子遊戲時不會殘留上一款的形狀。
 */
export const mockLayout = () => createSlotGridLayout(getSlotLayoutSource(GameConfigManager.GAMEID));

export const COINS = 20;

export const BET_CONFIG: Record<string, BetConfig> = {
    TWD: { min: '20', max: '1000', defaultBet: '20', levels: ['20', '40', '60', '100', '200', '400', '1000'] },
    USD: { min: '1', max: '50', defaultBet: '1', levels: ['1', '2', '3', '5', '10', '20', '50'] },
    IDR: { min: '3000', max: '150000', defaultBet: '3000', levels: ['3000', '6000', '9000', '15000', '30000', '60000', '150000'] },
};

/**
 * 取某個幣別的下注設定。
 *
 * @param currency 幣別代碼，例如 `TWD`。
 * @returns 該幣別的下注設定；沒有登記的幣別回 null。
 */
export function getBetConfig(currency: string): BetConfig | null {
    return BET_CONFIG[currency] ?? null;
}

/**
 * 把金額轉成 API 格式的字串：整數不帶小數點，其餘保留兩位並去掉尾端的 0。
 *
 * @param value 金額。
 * @returns 格式化後的字串，例如 `20`、`1.5`。
 */
export function amount(value: number): string {
    if (Number.isInteger(value)) return String(value);
    return value.toFixed(2).replace(/\.?0+$/, '');
}

/**
 * 取 0 到 max−1 的隨機整數。
 *
 * @param max 上界（不含）。
 * @returns 0 到 max−1 的整數；max 為 0 時回 0。
 */
export function randomInt(max: number): number {
    return Math.floor(Math.random() * max);
}

/**
 * Fisher–Yates 洗牌，不改動傳入的陣列。
 *
 * @param items 要洗的陣列。
 * @returns 洗亂順序的新陣列。
 */
export function shuffle<T>(items: T[]): T[] {
    const result = [...items];
    for (let i = result.length - 1; i > 0; i--) {
        const j = randomInt(i + 1);
        [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
}
