import { _decorator, Camera, Component, view } from "cc";

const { ccclass, property } = _decorator;

@ccclass("1003/CameraSyncOrtho")
export class CameraSyncOrtho extends Component {

    @property(Camera)
    sourceCamera: Camera = null!;

    private selfCamera: Camera = null!;

    /**
     * 抓到自己的攝影機，延一幀同步一次，並監聽畫布尺寸變化。
     *
     * 延一幀是因為 Canvas 要先調完自己的尺寸，同幀去讀來源攝影機拿到的還是舊值
     * （同 agent-pitfalls.md 坑 #1 的初始化時序問題）。
     */
    protected override onLoad(): void {
        this.selfCamera = this.getComponent(Camera)!;
        // 延一幀等 Canvas 先調完
        this.scheduleOnce(() => this.sync(), 0);
        view.on("canvas-resize", this.sync, this);
    }

    /**
     * 把來源攝影機的正交高度同步到自己身上，一樣延一幀執行。
     */
    private sync(): void {
        if (this.sourceCamera && this.selfCamera) {
            // 延一幀確保 Canvas 已更新 sourceCamera
            this.scheduleOnce(() => {
                this.selfCamera.orthoHeight = this.sourceCamera.orthoHeight;
            }, 0);
        }
    }

    /**
     * 解除畫布尺寸變化的監聽。
     */
    protected override onDestroy(): void {
        view.off("canvas-resize", this.sync, this);
    }
}
