import { _decorator, assetManager, Component, director, Node as CCNode, sp, sys } from 'cc';
import AppConfig from '../config/AppConfig';
import { WinTier } from '../config/GameConst';
import PresentationStore from '../config/PresentationStore';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import StoreManager from '../store/StoreManager';
import { GameViewAdapter } from './GameViewAdapter';
import { SPINE_ASSET_MAP } from './SpineAssetMap';
import AppAudio from '../audio/AppAudio';
import { EFFECTSMAP, REEL_STOP_NORMAL_PRIORITY, REEL_STOP_BY_KIND } from '../audio/AudioConfig';
import { SlotMachineView } from '../reel/view/SlotMachineView';
import ReelTimingDebugStore, { type ReelTimingOverride as ReelTiming, type ReelTimingTier } from '../config/ReelTimingDebugStore';
import { DEFAULT_REEL_CONFIG } from '../reel/ReelConfig';
import SceneSpeedStore, { SceneSpeedActivationMode, type SceneSpeedOverride } from '../config/SceneSpeedStore';
import { DEFAULT_SCENE_SPEED_CONFIG } from '../reel/SceneSpeedConfig';

const REEL_TIMING_GAME_ID = '1003';
const SCENE_SPEED_GAME_ID = '1003';
const SCENE_SPEED_RANGE = { min: 1, max: 3, step: 0.1 };

// 經典轉輪狀態機（不分速度檔）
type ClassicKey = 'beginDuration' | 'loopTime' | 'endDuration';
type ClassicEaseKey = 'beginEase' | 'endEase';
const CLASSIC_TIMING_RANGES: Record<ClassicKey, { min: number; max: number; step: number }> = {
    beginDuration: { min: 0.05, max: 1.5, step: 0.01 },
    loopTime: { min: 0.01, max: 0.3, step: 0.005 },
    endDuration: { min: 0.02, max: 1, step: 0.01 },
};

// 整體速度（一般/快/急速）拉桿的標籤，對應 GameMain.getTurboIndex() 的索引
const TIER_LABELS: [string, string, string] = ['一般', '快', '急速'];
type TierKey = Exclude<keyof ReelTimingTier, TierEaseKey>;
type TierEaseKey = 'tumbleClearEase' | 'tumbleFillEase' | 'fillEase';
const TIER_TIMING_RANGES: Record<TierKey, { min: number; max: number; step: number }> = {
    tumbleClear: { min: 0, max: 1, step: 0.01 },
    tumbleFill: { min: 0, max: 1, step: 0.01 },
    explode: { min: 0.05, max: 1, step: 0.01 },
    winFx: { min: 0.1, max: 2, step: 0.05 },
    fill: { min: 0.02, max: 0.5, step: 0.01 },
    fillStagger: { min: 0, max: 0.1, step: 0.005 },
};

// 對應 cc.TweenEasing，DebugPanel 不 import cc，這裡直接列字串清單給下拉選單用
const EASE_OPTIONS = ['linear', 'quadIn', 'quadOut', 'quadInOut', 'cubicIn', 'cubicOut', 'cubicInOut', 'sineIn', 'sineOut', 'sineInOut', 'backIn', 'backOut', 'backInOut', 'elasticIn', 'elasticOut', 'elasticInOut', 'bounceIn', 'bounceOut', 'bounceInOut'];

// 經典連續滾動轉輪狀態機（beginDuration/loopTime/endDuration/beginEase/endEase）在這個落球式
// 遊戲裡沒有真的跑完一輪，玩家看不出效果——先隱藏這組 UI，邏輯保留（其他 Core 共用遊戲可能用得到）
const SHOW_CLASSIC_REEL_SPIN_UI = false;

const { ccclass } = _decorator;

@ccclass('1003/DebugPanel')
export class DebugPanel extends Component {
    private root: HTMLElement | null = null;
    private contentEl: HTMLElement | null = null;
    private domAbortController: AbortController | null = null;
    private panelConfigChanged: (() => void) | null = null;

    private panelVisible = false;
    private dragging = false;
    private didDrag = false;
    private dragOffsetX = 0;
    private dragOffsetY = 0;

    // state
    private symbol: number | null = null;
    private count = 8;
    private line = 1;
    private win: { min: number; max: number } | null = null;
    /** 免費遊戲加局治具：強制第 1 局／每一局再觸發加局，用來驗演出與局數顯示 */
    private fgRetrigger: 'off' | 'first' | 'every' = 'off';

    // 轉輪節奏 + 消除補格掉落節奏 state（PM 線上調整用；只負責寫，GameMain 在每次 spin／消除補格前才讀取套用）
    // 只有一般節奏（tier）可調；快轉/急速轉改由下方「整體速度」倍率處理
    private reelTiming: ReelTiming = DEFAULT_REEL_CONFIG;
    private reelTimingDefault: ReelTiming | null = null;
    private reelTimingLoaded = false;

    // 整體 scene 加速倍率與生效模式 state
    private sceneSpeed: SceneSpeedOverride = DEFAULT_SCENE_SPEED_CONFIG;
    private sceneSpeedDefault: SceneSpeedOverride | null = null;
    private sceneSpeedLoaded = false;

    // Symbol 縮放倍率（即時套用到目前場上所有 reel 的 symbol，不記錄、不影響下一局），跟 NgSymbol 的正式預設值 1 對齊
    private symbolScale = 1;

    // 落地果凍效果（squash）強度，0=關閉、1=原始美術數值；套到 reelView 上，下次 spin 生效，跟 ReelView 的正式預設值 0.8 對齊
    private squashIntensity = 0.8;

    // spine 預覽 state
    private spineKey: string = Object.keys(SPINE_ASSET_MAP).sort()[0] ?? '';
    private spineSkin: string = '';
    private spineAnim: string = 'animation';
    private spineLoop: boolean = true;
    private spineScale: number = 1;
    private spinePreviewNode: CCNode | null = null;
    /** key -> 該資產實際的皮膚名稱清單（從已載入的 SkeletonData 讀出來，不是猜的） */
    private spineSkinOptions: string[] = [];
    /** key -> 該資產實際的動畫名稱清單，同樣從 SkeletonData 讀出來，不同資產不會同名 */
    private spineAnimOptions: string[] = [];
    private spineMetaLoading = false;
    private spineDataCache: Map<string, sp.SkeletonData> = new Map();

    /** 只在 DEBUG 且有 DOM 的環境建面板；同時訂閱設定變動並預載 spine 清單。 */
    protected override onLoad(): void {
        // isNative 不會在原生去建 DOM 面板
        if (sys.isNative || typeof document === 'undefined' || !AppConfig.DEBUG) {
            return;
        }
        this.buildPanel();
        this.panelConfigChanged = gameRuntimeEventBus.on(GAME_EVENT_TYPE.GAME_CONFIG_DATA_CHANGED, () => this.render());
        this.loadSpineMeta(this.spineKey);

        // __audioDebug.playEffect(__audioDebug.EFFECTSMAP.BIGWIN_LOOP)
        // __audioDebug.fadeOut(__audioDebug.EFFECTSMAP.BIGWIN_LOOP)
        // __audioDebug.playLoop(__audioDebug.EFFECTSMAP.BIGWIN_LOOP)
        // __audioDebug.stopLoop(__audioDebug.EFFECTSMAP.BIGWIN_LOOP, __audioDebug.EFFECTSMAP.WIN_END)
        // __audioDebug.testReelStopPriority('scatter')  // 應該播 REEL_STOP_2；不帶參數應該播 REEL_STOP_1
        // __audioDebug.fadeMusic(0.5, 2) // 2 秒內淡出到 50% 音量
        // __audioDebug.pauseMusic()
        // __audioDebug.resumeMusic()
        (window as any).__audioDebug = {
            EFFECTSMAP,
            playEffect: (path: string, allowOverlap?: boolean) => AppAudio.getInstance().playEffect(path, { allowOverlap }),
            fadeOut: (path: string) => AppAudio.getInstance().stopEffectWithFade(path),
            playLoop: (path: string) => AppAudio.getInstance().playLoopEffect(path),
            stopLoop: (path: string, endPath?: string) => AppAudio.getInstance().stopLoopEffect(path, endPath),
            playHighestPriority: (candidates: { path: string; priority: number }[]) => AppAudio.getInstance().playHighestPriority(candidates),
            testReelStopPriority: (kind?: keyof typeof REEL_STOP_BY_KIND) => AppAudio.getInstance().playHighestPriority([{ path: EFFECTSMAP.REEL_STOP_1, priority: REEL_STOP_NORMAL_PRIORITY }, ...(kind && REEL_STOP_BY_KIND[kind] ? [REEL_STOP_BY_KIND[kind]!] : [])]),
            fadeMusic: (ratio: number, duration?: number) => AppAudio.getInstance().fadeMusicVolume(ratio, duration, () => console.log('[audioDebug] fadeMusic 完成', ratio)),
            pauseMusic: () => AppAudio.getInstance().pauseMusic(),
            resumeMusic: () => AppAudio.getInstance().resumeMusic(),
        };
    }

    /** 收掉訂閱、DOM 事件、debug control 與 spine 預覽，面板節點一併移除。 */
    protected override onDestroy(): void {
        this.panelConfigChanged?.();
        this.panelConfigChanged = null;
        this.domAbortController?.abort();
        this.domAbortController = null;
        this.setDebugControl(null);
        this.closeSpinePreview();
        this.root?.remove();
        this.root = null;
        this.contentEl = null;
        this.dragging = false;
        this.didDrag = false;
        this.panelVisible = false;
    }

    // ─── Build HTML ───────────────────────────────────────────

    /** 建出面板的 DOM 骨架（開關鈕 ＋ 內容區）並掛到 document.body。 */
    private buildPanel(): void {
        const root = document.createElement('div');
        root.style.cssText = ['position:fixed', 'top:10px', 'right:10px', 'z-index:9999', 'font-family:monospace', 'font-size:12px', 'user-select:none'].join(';');
        const toggle = this.makeEl('button', '🎰 Debug');
        toggle.style.cssText = ['display:block', 'width:100%', 'padding:4px 10px', 'background:#222', 'color:#f0c040', 'border:1px solid #555', 'border-radius:6px 6px 0 0', 'cursor:pointer', 'font-size:12px', 'font-weight:bold'].join(';');
        const content = document.createElement('div');
        content.style.cssText = ['background:rgba(15,15,15,0.95)', 'color:#ddd', 'border:1px solid #555', 'border-top:none', 'border-radius:0 0 6px 6px', 'display:none', 'padding:10px', 'width:290px', 'max-height:80vh', 'overflow-y:auto'].join(';');
        root.appendChild(toggle);
        root.appendChild(content);
        document.body.appendChild(root);
        this.root = root;
        this.contentEl = content;
        this.bindDomEvents(toggle);
        this.render();
    }

    /**
     * 綁面板的 DOM 事件（開關、拖曳）。用 AbortController 管理，重綁時先 abort 舊的。
     *
     * @param toggle 面板頂端的開關按鈕。
     */
    private bindDomEvents(toggle: HTMLElement): void {
        const controller = new AbortController();
        const { signal } = controller;
        this.domAbortController?.abort();
        this.domAbortController = controller;
        toggle.addEventListener(
            'mousedown',
            (event: MouseEvent) => {
                const root = this.root;
                if (!root) return;
                this.dragging = true;
                this.didDrag = false;
                this.dragOffsetX = event.clientX - root.offsetLeft;
                this.dragOffsetY = event.clientY - root.offsetTop;
                event.preventDefault();
            },
            { signal }
        );
        document.addEventListener(
            'mousemove',
            (event: MouseEvent) => {
                const root = this.root;
                if (!this.dragging || !root) return;
                this.didDrag = true;
                root.style.left = `${event.clientX - this.dragOffsetX}px`;
                root.style.top = `${event.clientY - this.dragOffsetY}px`;
                root.style.right = 'auto';
            },
            { signal }
        );
        document.addEventListener(
            'mouseup',
            () => {
                if (this.dragging && !this.didDrag) {
                    this.setPanelVisible(!this.panelVisible);
                }
                this.dragging = false;
            },
            { signal }
        );
    }

    /**
     * 開關面板內容區。
     *
     * @param visible 要不要顯示。
     */
    private setPanelVisible(visible: boolean): void {
        this.panelVisible = visible;
        if (this.contentEl) {
            this.contentEl.style.display = visible ? 'block' : 'none';
        }
    }

    /** 依目前 state 整個重畫面板內容；每次按鈕互動後都會重跑，按鈕的選取狀態才會更新。 */
    private render(): void {
        const p = this.contentEl;
        if (!p) return;
        p.innerHTML = '';

        // ── 關閉鈕（面板不再點外部自動關閉，PM 調參數時可以一直開著邊玩邊看）──

        const closeBtn = this.toggleBtn('✕ 關閉面板', false, () => this.setPanelVisible(false));
        closeBtn.style.cssText += 'width:100%;margin-bottom:6px;';
        p.appendChild(closeBtn);

        // ── User ID ──

        const userID = StoreManager.getInstance().getHttpClientStore().userID || '(未登入)';
        p.appendChild(this.makeEl('div', `UserID: ${userID}`, 'color:#9cf;font-size:11px;margin-bottom:6px;padding:4px 6px;' + 'background:#1a1a2a;border-radius:4px;border:1px solid #335;' + 'word-break:break-all;'));

        // ── 免費遊戲每局報獎 ──

        p.appendChild(this.section('免費遊戲每局報獎'));
        const fgEnableGrid = this.row('flex-wrap:wrap;gap:4px;');
        const fgEnableOptions: [string, boolean][] = [
            ['關閉(原本)', false],
            ['開啟', true],
        ];
        const presentationStore = PresentationStore.getInstance();
        for (const [label, enabled] of fgEnableOptions) {
            const active = presentationStore.config.featureRoundWinPresentationEnabled === enabled;
            fgEnableGrid.appendChild(
                this.toggleBtn(label, active, () => {
                    presentationStore.setFeatureRoundWinPresentationEnabled(enabled);
                    this.updateControl();
                })
            );
        }
        p.appendChild(fgEnableGrid);

        const fgWinTierGrid = this.row('flex-wrap:wrap;gap:4px;');
        const fgWinTierOptions: [string, WinTier][] = [
            ['Big', WinTier.BIG],
            ['Mega', WinTier.MEGA],
            ['Super', WinTier.SUPER],
            ['Epic', WinTier.EPIC],
        ];
        for (const [label, minTier] of fgWinTierOptions) {
            const active = presentationStore.config.featureRoundWinPresentationMinTier === minTier;
            fgWinTierGrid.appendChild(
                this.toggleBtn(label, active, () => {
                    presentationStore.setFeatureRoundWinPresentationMinTier(minTier);
                    this.updateControl();
                })
            );
        }
        p.appendChild(fgWinTierGrid);

        // 免費遊戲加局（GDD 4.3）。自然發生率是每局 3%（約三成的 FG 會遇到一次），手動玩幾乎
        // 驗不到，所以給強制加局的治具；它只影響 mock 產生的資料，不改玩法常數。
        // 「第1局加局」一次 FG 剛好看到一次加局；「每局都加局」會一路加到局數安全閥，是壓力測試用的。
        p.appendChild(this.section('免費遊戲加局（治具）'));
        const fgRetriggerGrid = this.row('flex-wrap:wrap;gap:4px;');
        const fgRetriggerOptions: [string, 'off' | 'first' | 'every'][] = [
            ['關閉(原本機率)', 'off'],
            ['第1局加局', 'first'],
            ['每局都加局', 'every'],
        ];
        for (const [label, mode] of fgRetriggerOptions) {
            fgRetriggerGrid.appendChild(
                this.toggleBtn(label, this.fgRetrigger === mode, () => {
                    this.fgRetrigger = mode;
                    this.updateControl();
                })
            );
        }
        p.appendChild(fgRetriggerGrid);

        // ── 轉輪節奏（PM 線上調整用）──

        this.ensureReelTimingLoaded();
        const classicField = (label: string, key: ClassicKey): HTMLElement => {
            const range = CLASSIC_TIMING_RANGES[key];
            const row = this.row('gap:6px;align-items:center;');
            row.appendChild(this.makeEl('span', label, 'font-size:11px;color:#aaa;min-width:70px;'));
            const slider = document.createElement('input');
            slider.type = 'range';
            slider.min = String(range.min);
            slider.max = String(range.max);
            slider.step = String(range.step);
            slider.value = String(this.reelTiming[key]);
            slider.style.cssText = 'flex:1;';
            const valueLabel = this.makeEl('span', this.reelTiming[key].toFixed(3), 'min-width:44px;text-align:right;font-size:11px;color:#ddd;');
            slider.oninput = () => {
                const v = parseFloat(slider.value);
                if (!Number.isFinite(v)) return;
                this.reelTiming = { ...this.reelTiming, [key]: v };
                valueLabel.textContent = v.toFixed(3);
                this.saveReelTiming();
            };
            row.appendChild(slider);
            row.appendChild(valueLabel);
            return row;
        };
        const classicEaseField = (label: string, key: ClassicEaseKey): HTMLElement => {
            const row = this.row('gap:6px;align-items:center;');
            row.appendChild(this.makeEl('span', label, 'font-size:11px;color:#aaa;min-width:70px;'));
            const select = document.createElement('select');
            select.style.cssText = 'flex:1;background:#222;color:#ddd;border:1px solid #555;border-radius:4px;padding:3px;font-family:monospace;font-size:11px;';
            for (const name of EASE_OPTIONS) {
                const opt = document.createElement('option');
                opt.value = name;
                opt.textContent = name;
                if (name === this.reelTiming[key]) opt.selected = true;
                select.appendChild(opt);
            }
            select.onchange = () => {
                this.reelTiming = { ...this.reelTiming, [key]: select.value };
                this.saveReelTiming();
            };
            row.appendChild(select);
            return row;
        };
        // 只保留一般節奏（tier）可調，快轉/急速轉改由下方「整體速度」倍率處理
        const tierField = (label: string, key: TierKey): HTMLElement => {
            const range = TIER_TIMING_RANGES[key];
            const row = this.row('gap:6px;align-items:center;');
            row.appendChild(this.makeEl('span', label, 'font-size:11px;color:#aaa;min-width:70px;'));
            const slider = document.createElement('input');
            slider.type = 'range';
            slider.min = String(range.min);
            slider.max = String(range.max);
            slider.step = String(range.step);
            slider.value = String(this.reelTiming.tier[key]);
            slider.style.cssText = 'flex:1;';
            const valueLabel = this.makeEl('span', this.reelTiming.tier[key].toFixed(3), 'min-width:44px;text-align:right;font-size:11px;color:#ddd;');
            slider.oninput = () => {
                const v = parseFloat(slider.value);
                if (!Number.isFinite(v)) return;
                this.reelTiming = { ...this.reelTiming, tier: { ...this.reelTiming.tier, [key]: v } };
                valueLabel.textContent = v.toFixed(3);
                this.saveReelTiming();
            };
            row.appendChild(slider);
            row.appendChild(valueLabel);
            return row;
        };
        const tierEaseField = (label: string, key: TierEaseKey): HTMLElement => {
            const row = this.row('gap:6px;align-items:center;');
            row.appendChild(this.makeEl('span', label, 'font-size:11px;color:#aaa;min-width:70px;'));
            const select = document.createElement('select');
            select.style.cssText = 'flex:1;background:#222;color:#ddd;border:1px solid #555;border-radius:4px;padding:3px;font-family:monospace;font-size:11px;';
            for (const name of EASE_OPTIONS) {
                const opt = document.createElement('option');
                opt.value = name;
                opt.textContent = name;
                if (name === this.reelTiming.tier[key]) opt.selected = true;
                select.appendChild(opt);
            }
            select.onchange = () => {
                this.reelTiming = { ...this.reelTiming, tier: { ...this.reelTiming.tier, [key]: select.value } };
                this.saveReelTiming();
            };
            row.appendChild(select);
            return row;
        };
        if (SHOW_CLASSIC_REEL_SPIN_UI) {
            p.appendChild(this.section('轉輪節奏（開始→等速→結束，下次 spin 生效）'));
            p.appendChild(classicField('開始加速(秒)', 'beginDuration'));
            p.appendChild(classicEaseField('開始緩動', 'beginEase'));
            p.appendChild(classicField('等速轉動(秒/格)', 'loopTime'));
            p.appendChild(classicField('結束減速(秒)', 'endDuration'));
            p.appendChild(classicEaseField('結束緩動', 'endEase'));
        }

        p.appendChild(this.section('初始盤面落定節奏－一般（玩家實際看到的「開始→落下→停止」，下次 spin 生效；快轉/急速轉改用下方整體速度倍率）'));
        p.appendChild(tierField('清除舊盤面(秒)', 'tumbleClear'));
        p.appendChild(tierEaseField('清除緩動', 'tumbleClearEase'));
        p.appendChild(tierField('落下到位(秒)', 'tumbleFill'));
        p.appendChild(tierEaseField('落下緩動', 'tumbleFillEase'));

        p.appendChild(this.section('消除補格掉落節奏－一般（下次消除生效；快轉/急速轉改用下方整體速度倍率）'));
        p.appendChild(tierField('消除動畫(秒)', 'explode'));
        p.appendChild(tierField('中獎發光(秒)', 'winFx'));
        p.appendChild(tierField('掉落耗時(秒)', 'fill'));
        p.appendChild(tierField('每欄延遲(秒)', 'fillStagger'));
        p.appendChild(tierEaseField('掉落緩動', 'fillEase'));

        const timingBtnRow = this.row('gap:4px;margin-top:4px;');
        timingBtnRow.appendChild(this.toggleBtn('匯出 JSON', false, () => this.exportReelTiming()));
        timingBtnRow.appendChild(this.toggleBtn('恢復預設', false, () => this.resetReelTiming()));
        p.appendChild(timingBtnRow);

        // ── 整體速度與生效模式──

        this.ensureSceneSpeedLoaded();
        p.appendChild(this.section('整體速度（轉動期間：下一局生效／整場持續：目前檔位立即生效）'));
        TIER_LABELS.forEach((label, idx) => {
            const sceneSpeedRow = this.row('gap:6px;align-items:center;');
            sceneSpeedRow.appendChild(this.makeEl('span', label, 'font-size:11px;color:#aaa;min-width:70px;'));
            const sceneSpeedSlider = document.createElement('input');
            sceneSpeedSlider.type = 'range';
            sceneSpeedSlider.min = String(SCENE_SPEED_RANGE.min);
            sceneSpeedSlider.max = String(SCENE_SPEED_RANGE.max);
            sceneSpeedSlider.step = String(SCENE_SPEED_RANGE.step);
            sceneSpeedSlider.value = String(this.sceneSpeed.speedFactors[idx]);
            sceneSpeedSlider.style.cssText = 'flex:1;';
            const sceneSpeedValueLabel = this.makeEl('span', `${this.sceneSpeed.speedFactors[idx].toFixed(1)}x`, 'min-width:44px;text-align:right;font-size:11px;color:#ddd;');
            sceneSpeedSlider.oninput = () => {
                const v = parseFloat(sceneSpeedSlider.value);
                if (!Number.isFinite(v)) return;
                const speedFactors = [...this.sceneSpeed.speedFactors] as [number, number, number];
                speedFactors[idx] = v;
                this.sceneSpeed = { ...this.sceneSpeed, speedFactors };
                sceneSpeedValueLabel.textContent = `${v.toFixed(1)}x`;
                this.saveSceneSpeed();
            };
            sceneSpeedRow.appendChild(sceneSpeedSlider);
            sceneSpeedRow.appendChild(sceneSpeedValueLabel);
            p.appendChild(sceneSpeedRow);
        });
        const activationModeRow = this.row('gap:4px;margin-top:4px;');
        activationModeRow.appendChild(this.toggleBtn('轉動期間', this.sceneSpeed.activationMode === SceneSpeedActivationMode.SPIN_WINDOW, () => {
            this.sceneSpeed = { ...this.sceneSpeed, activationMode: SceneSpeedActivationMode.SPIN_WINDOW };
            this.saveSceneSpeed();
            this.render();
        }));
        activationModeRow.appendChild(this.toggleBtn('整場持續', this.sceneSpeed.activationMode === SceneSpeedActivationMode.GAME_WIDE, () => {
            this.sceneSpeed = { ...this.sceneSpeed, activationMode: SceneSpeedActivationMode.GAME_WIDE };
            this.saveSceneSpeed();
            this.render();
        }));
        p.appendChild(activationModeRow);
        p.appendChild(this.toggleBtn('恢復預設', false, () => this.resetSceneSpeed()));

        // ── Symbol 縮放（即時套用到目前場上所有 reel 的 symbol，不記錄）──

        p.appendChild(this.section('Symbol 縮放（即時套用，不記錄，重進場景會還原）'));
        const symbolScaleRow = this.row('gap:6px;align-items:center;');
        symbolScaleRow.appendChild(this.makeEl('span', '縮放', 'font-size:11px;color:#aaa;min-width:70px;'));
        const symbolScaleSlider = document.createElement('input');
        symbolScaleSlider.type = 'range';
        symbolScaleSlider.min = '0.5';
        symbolScaleSlider.max = '1.5';
        symbolScaleSlider.step = '0.01';
        symbolScaleSlider.value = String(this.symbolScale);
        symbolScaleSlider.style.cssText = 'flex:1;';
        const symbolScaleValueLabel = this.makeEl('span', this.symbolScale.toFixed(2), 'min-width:44px;text-align:right;font-size:11px;color:#ddd;');
        symbolScaleSlider.oninput = () => {
            const v = parseFloat(symbolScaleSlider.value);
            if (!Number.isFinite(v)) return;
            this.symbolScale = v;
            symbolScaleValueLabel.textContent = v.toFixed(2);
            this.applySymbolScale();
        };
        symbolScaleRow.appendChild(symbolScaleSlider);
        symbolScaleRow.appendChild(symbolScaleValueLabel);
        p.appendChild(symbolScaleRow);

        // ── 落地果凍效果（squash，套用在初始盤落地，下次 spin 生效）──

        p.appendChild(this.section('落地果凍效果（squash，下次 spin 生效）'));
        const squashRow = this.row('gap:6px;align-items:center;');
        squashRow.appendChild(this.makeEl('span', '強度', 'font-size:11px;color:#aaa;min-width:70px;'));
        const squashSlider = document.createElement('input');
        squashSlider.type = 'range';
        squashSlider.min = '0';
        squashSlider.max = '2';
        squashSlider.step = '0.05';
        squashSlider.value = String(this.squashIntensity);
        squashSlider.style.cssText = 'flex:1;';
        const squashValueLabel = this.makeEl('span', this.squashIntensity.toFixed(2), 'min-width:44px;text-align:right;font-size:11px;color:#ddd;');
        squashSlider.oninput = () => {
            const v = parseFloat(squashSlider.value);
            if (!Number.isFinite(v)) return;
            this.squashIntensity = v;
            squashValueLabel.textContent = v.toFixed(2);
            this.applySquashIntensity();
        };
        squashRow.appendChild(squashSlider);
        squashRow.appendChild(squashValueLabel);
        p.appendChild(squashRow);
        p.appendChild(this.toggleBtn('恢復預設', false, () => {
            this.squashIntensity = 1;
            this.applySquashIntensity();
            this.render();
        }));

        // ── Status ──

        p.appendChild(this.section('當前 debug_result_control'));
        const control = this.buildControl();
        const hasAny = Object.keys(control).length > 0;
        p.appendChild(this.makeEl('pre', hasAny ? JSON.stringify(control, null, 2) : '（未啟用）', `background:#111;padding:6px;border-radius:4px;font-size:10px;` + `color:${hasAny ? '#6f6' : '#666'};` + 'white-space:pre-wrap;word-break:break-all;margin:4px 0;'));

        // ── Clear ──

        const clear = this.toggleBtn('清除所有設定', false, () => this.clearControl());
        clear.style.cssText += 'width:100%;background:#5a1a1a;margin-top:6px;';
        p.appendChild(clear);
    }

    // ─── Logic ───────────────────────────────────────────────

    /** 套用目前 state 到 debug control，並重畫面板。 */
    private updateControl(): void {
        this.apply();
        this.render();
    }

    /** 清掉所有 debug 設定（符號控制、贏分區間、加局治具），回到預設。 */
    private clearControl(): void {
        this.symbol = null;
        this.count = 8;
        this.line = 1;
        this.win = null;
        this.fgRetrigger = 'off';
        this.updateControl();
    }

    /**
     * 依目前 state 組出要塞進 `__slotApiDebugControl__` 的物件。
     *
     * @returns debug control 物件；沒有任何設定時是空物件。
     */
    private buildControl(): Record<string, unknown> {
        const control: Record<string, unknown> = {};
        if (this.symbol !== null) {
            control.symbol_control = {
                symbol: this.symbol,
                count: this.count,
                line: this.line,
            };
        }
        if (this.win !== null) {
            control.win = { ...this.win };
        }
        if (this.fgRetrigger !== 'off') {
            control.free_game = { retrigger: this.fgRetrigger };
        }
        return control;
    }

    /** 把 {@link buildControl} 的結果寫進 debug control；全空就寫 null（等於關閉）。 */
    private apply(): void {
        const control = this.buildControl();
        this.setDebugControl(Object.keys(control).length > 0 ? control : null);
    }

    /**
     * 寫入 debug control。HttpClientStore 與 globalThis 兩邊都要寫——mock 引擎讀的是後者。
     *
     * @param value 要套用的設定；null 代表關閉。
     */
    private setDebugControl(value: Record<string, unknown> | null): void {
        StoreManager.getInstance().getHttpClientStore().debugControl = value;
        (globalThis as any).__slotApiDebugControl__ = value;
    }

    // ─── 轉輪節奏（PM 線上調整用，跟 debug_result_control 無關）───

    /**
     * 場上目前顯示中的 SlotMachineView（不分 portrait／landscape，直接找場景裡 active 的那個）。
     *
     * @returns 找到的 view；場景還沒好或都不在畫面上時為 null。
     */
    private resolveSlotMachineView(): SlotMachineView | null {
        const scene = director.getScene();
        if (!scene) return null;
        return scene.getComponentsInChildren(SlotMachineView).find((view) => view.node.activeInHierarchy) ?? null;
    }

    /** 把目前滑桿的縮放倍率即時套到場上所有 reel 的 symbol；找不到場上轉輪就什麼都不做 */
    private applySymbolScale(): void {
        const view = this.resolveSlotMachineView();
        view?.reelViews.forEach((rv) => rv.setSymbolScale(this.symbolScale));
    }

    /** 把目前滑桿的果凍強度存到場上所有 reel；tween 只在下次 tumbleFill（下次 spin）才會讀到 */
    private applySquashIntensity(): void {
        const view = this.resolveSlotMachineView();
        view?.reelViews.forEach((rv) => rv.setSquashIntensity(this.squashIntensity));
    }

    /** 第一次真的拿到場上轉輪時：記錄 Editor 原始基準值（給「恢復預設」用），並讀出先前存的覆寫值（若有）給 UI 顯示；
     *  不在這裡呼叫 applySpeed()——套用時機交給 SlotGameMain 在每次 spin 開始前處理。 */
    private ensureReelTimingLoaded(): void {
        if (this.reelTimingLoaded) return;
        // getSpeed()/getEase() 讀得到轉輪自己的 beginDuration/loopTime/endDuration/beginEase/endEase；
        // explode/winFx/fill/fillStagger/fillEase 是 GameMain.cascadeTiming() 的欄位，DebugPanel 沒有
        // 現成的即時讀法。基準值優先用遊戲啟動時已載入的 reelConfig.json 本地端預設值（GameMain.gameInit()
        // 呼叫 setLocalDefault() 設定），確保「恢復預設」永遠對齊目前的 reelConfig.json，不用手動同步兩份；
        // 萬一還沒載入完成（理論上不會，DebugPanel 比遊戲晚渲染），才退回 ReelConfig.ts 的靜態常數。
        const view = this.resolveSlotMachineView();
        const live = view?.getSpeed();
        if (!live) return;
        const liveEase = view?.getEase();
        const base = ReelTimingDebugStore.getLocalDefault(REEL_TIMING_GAME_ID) ?? DEFAULT_REEL_CONFIG;
        const tier = { ...base.tier };
        this.reelTimingDefault = { ...base, ...live, ...liveEase, tier };
        this.reelTiming = ReelTimingDebugStore.get(REEL_TIMING_GAME_ID) ?? this.reelTimingDefault;
        this.reelTimingLoaded = true;
    }

    /** 只存進 ReelTimingDebugStore，不直接套到場上轉輪——下次 spin 開始前由 SlotGameMain 讀取套用 */
    private saveReelTiming(): void {
        ReelTimingDebugStore.set(REEL_TIMING_GAME_ID, this.reelTiming);
        console.log(`[DebugPanel] 轉輪節奏已存進 ReelTimingDebugStore（key="${REEL_TIMING_GAME_ID}"）`, this.reelTiming);
    }

    /** 轉輪節奏回到預設值並重畫面板。 */
    private resetReelTiming(): void {
        if (!this.reelTimingDefault) return;
        this.reelTiming = { ...this.reelTimingDefault };
        this.saveReelTiming();
        this.render();
    }

    // ─── 整體速度（PM 線上調整用）───

    /** 基準值優先用遊戲啟動時已載入的 reelConfig.json 本地端預設值，確保「恢復預設」永遠對齊目前的 reelConfig.json */
    private ensureSceneSpeedLoaded(): void {
        if (this.sceneSpeedLoaded) return;
        const base = SceneSpeedStore.getLocalDefault(SCENE_SPEED_GAME_ID) ?? DEFAULT_SCENE_SPEED_CONFIG;
        this.sceneSpeedDefault = { ...base, speedFactors: [...base.speedFactors] as [number, number, number] };
        this.sceneSpeed = SceneSpeedStore.get(SCENE_SPEED_GAME_ID) ?? this.sceneSpeedDefault;
        this.sceneSpeedLoaded = true;
    }

    /** 存進 SceneSpeedStore 並通知 GameMain 依生效模式處理 */
    private saveSceneSpeed(): void {
        SceneSpeedStore.set(SCENE_SPEED_GAME_ID, this.sceneSpeed);
        console.log(`[DebugPanel] 整體速度已存進 SceneSpeedStore（key="${SCENE_SPEED_GAME_ID}"）`, this.sceneSpeed);
    }

    /** 整體 scene 加速倍率回到預設值並重畫面板。 */
    private resetSceneSpeed(): void {
        if (!this.sceneSpeedDefault) return;
        this.sceneSpeed = { ...this.sceneSpeedDefault, speedFactors: [...this.sceneSpeedDefault.speedFactors] as [number, number, number] };
        this.saveSceneSpeed();
        this.render();
    }

    /** 把目前的轉輪節奏印成 JSON（PM 調好之後貼回設定檔用）。 */
    private exportReelTiming(): void {
        // 跟整體速度共用同一份 reelConfig.json，匯出時一併帶上 speedFactors
        const payload = { ...this.reelTiming, speedFactors: this.sceneSpeed.speedFactors, speedActivationMode: this.sceneSpeed.activationMode, exportedAt: new Date().toISOString() };
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `reel-timing-1003-${Date.now()}.json`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
    }

    // ─── Spine 預覽（美術資產盤點用，跟主流程完全無關，只掛在 popupRoot 底下）───

    /** 載入（或從 cache 取）指定 key 的 SkeletonData，不掛任何節點。 */
    private loadSpineData(key: string, callback: (data: sp.SkeletonData | null) => void): void {
        const cached = this.spineDataCache.get(key);
        if (cached) {
            callback(cached);
            return;
        }
        const uuid = SPINE_ASSET_MAP[key];
        if (!uuid) {
            console.warn(`[DebugPanel] Spine 預覽找不到資產: ${key}`);
            callback(null);
            return;
        }
        assetManager.loadAny({ uuid }, (err: Error | null, skeletonData: sp.SkeletonData) => {
            if (err || !skeletonData) {
                console.warn(`[DebugPanel] Spine 資產載入失敗: ${key}`, err);
                callback(null);
                return;
            }
            this.spineDataCache.set(key, skeletonData);
            callback(skeletonData);
        });
    }

    /**
     * 選好資產後，讀出該資產實際的皮膚 ＋ 動畫名稱清單（不同資產不一定同名，直接從 SkeletonData 讀，不用猜）。
     *
     * @param key 資產代號，對應 `SPINE_ASSET_MAP`。
     */
    private loadSpineMeta(key: string): void {
        this.spineMetaLoading = true;
        this.spineSkinOptions = [];
        this.spineAnimOptions = [];
        this.render();
        this.loadSpineData(key, (skeletonData) => {
            this.spineMetaLoading = false;
            const runtimeData = skeletonData?.getRuntimeData() ?? null;
            this.spineSkinOptions = runtimeData?.skins.map((s) => s.name) ?? [];
            this.spineAnimOptions = runtimeData?.animations.map((a) => a.name) ?? [];
            if (!this.spineSkin || !this.spineSkinOptions.includes(this.spineSkin)) {
                this.spineSkin = this.spineSkinOptions[0] ?? '';
            }
            if (!this.spineAnim || !this.spineAnimOptions.includes(this.spineAnim)) {
                this.spineAnim = this.spineAnimOptions[0] ?? '';
            }
            this.render();
        });
    }

    /**
     * 動態載入指定的 spine 資產，掛到 popupRoot 底下播放。
     *
     * @param key 資產代號，對應 `SPINE_ASSET_MAP`。
     * @param skin 要套的皮膚；不給就用資產預設的。
     * @param animName 要播的動畫名稱。
     * @param loop 是否循環播放。
     * @param scale 預覽節點的縮放倍率。
     */
    private previewSpine(key: string, skin: string | undefined, animName: string, loop: boolean, scale: number): void {
        this.loadSpineData(key, (skeletonData) => {
            if (!skeletonData) return;
            const root = this.resolvePreviewRoot();
            if (!root) {
                console.warn('[DebugPanel] Spine 預覽找不到 popupRoot（場景可能還沒準備好）');
                return;
            }
            this.closeSpinePreview();
            const node = new CCNode(`SpinePreview_${key}`);
            root.addChild(node);
            node.setPosition(0, 0, 0);
            node.setScale(scale, scale, 1);
            const skel = node.addComponent(sp.Skeleton);
            skel.skeletonData = skeletonData;
            try {
                if (skin) skel.setSkin(skin);
                skel.setAnimation(0, animName, loop);
            } catch (e) {
                console.warn(`[DebugPanel] Spine 預覽播放失敗（皮膚或動畫名稱可能不存在）: ${key} / skin=${skin ?? '(預設)'} / anim=${animName}`, e);
            }
            this.spinePreviewNode = node;
        });
    }

    /** 關掉 spine 預覽並銷毀預覽節點。 */
    private closeSpinePreview(): void {
        if (this.spinePreviewNode?.isValid) {
            this.spinePreviewNode.destroy();
        }
        this.spinePreviewNode = null;
    }

    /**
     * 找 spine 預覽要掛的父節點。
     *
     * @returns 目前顯示中的 GameViewAdapter 的 popupRoot；找不到時為 null。
     */
    private resolvePreviewRoot(): CCNode | null {
        return this.resolveActiveAdapter()?.popupRoot ?? null;
    }

    /**
     * 場上目前顯示中的 GameViewAdapter。
     *
     * @returns 找到的 adapter；都不在畫面上時為 null。
     */
    private resolveActiveAdapter(): GameViewAdapter | null {
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return null;
        return scene.getComponentsInChildren(GameViewAdapter).find((a) => a.node.name === adapterName) ?? null;
    }

    // ─── DOM helpers ─────────────────────────────────────────

    /**
     * 產生一個區塊標題。
     *
     * @param title 標題文字。
     * @returns 標題元素。
     */
    private section(title: string): HTMLElement {
        return this.makeEl('div', title, 'color:#f0c040;font-weight:bold;margin:8px 0 4px;' + 'border-bottom:1px solid #444;padding-bottom:2px;' + 'font-size:11px;');
    }

    /**
     * 產生一列（flex 容器）。
     *
     * @param extraStyle 追加的行內樣式。
     * @returns 列元素。
     */
    private row(extraStyle = ''): HTMLElement {
        return this.makeEl('div', '', `display:flex;margin-bottom:4px;${extraStyle}`);
    }

    private toggleBtn(label: string, active: boolean, onClick: () => void): HTMLButtonElement {
        const button = document.createElement('button');
        button.textContent = label;
        button.style.cssText = ['padding:3px 8px', 'border-radius:4px', 'border:1px solid #555', 'cursor:pointer', 'font-family:monospace', 'font-size:11px', `background:${active ? '#3a6a3a' : '#2a2a2a'}`, `color:${active ? '#efe' : '#ccc'}`].join(';');
        button.onclick = onClick;
        return button;
    }

    /**
     * 產生一個帶文字與樣式的元素。
     *
     * @param tag 標籤名稱。
     * @param text 文字內容。
     * @param style 行內樣式。
     * @returns 建好的元素。
     */
    private makeEl(tag: string, text: string, style = ''): HTMLElement {
        const element = document.createElement(tag);
        element.textContent = text;
        if (style) {
            element.style.cssText = style;
        }
        return element;
    }
}
