import { JsonAsset, Sprite, SpriteFrame } from "cc";
import AppAssetBundle from "../utils/AppAssetBundle";
import { BASE_EVENT_ID, BASE_EVENT_TYPE, baseRuntimeEventBus } from "../events/BaseRuntimeEventBus";

type LanguageCodeWithLocale = keyof typeof LANGUAGE_MAP;
type LanguageCode = (typeof LANGUAGE_MAP)[LanguageCodeWithLocale];

/**
 * 多语系数据存储
 * @example
 * setLanguageMap({
 *     "view.title": "你好",
 * });
 */
const languageMap = {} as Record<LanguageCode, string>;

/**
 * 设置多语系数据，以 merge 方式更新
 */
export function setLanguageMap(map: Record<string, string>): void {
    Object.assign(languageMap, map);
}

/**
 * 初始化語言設定
 * @param initLanguage - 初始語言碼，可以是帶地區碼的語言碼（如 "en-US"）或簡化的語言碼（如 "en"）
 * @returns 實際設置的語言碼（簡化形式）e.g. "en"
 * @default 語言碼為 "en"
 */
export function i18nInit(
    initLanguage: LanguageCodeWithLocale | LanguageCode | string
): LanguageCode {
    const languageCode: LanguageCode =
        LANGUAGE_MAP[initLanguage as LanguageCodeWithLocale] ||
        (Object.values(LANGUAGE_MAP).includes(initLanguage as LanguageCode)
            ? (initLanguage as LanguageCode)
            : defaultLanguage);
    currentLanguage.set(languageCode);
    return languageCode;
}

globalThis.i18nInit = i18nInit;

export function getLocalizedString(searchKey: LanguageCode | string): string {
    return languageMap[searchKey as LanguageCode] ?? searchKey;
}

/**
 * 固定語言翻譯表快取，跟目前使用中的 languageMap 分開存放，不隨 switchLanguage 變動。
 * 給「不論目前語系為何，永遠顯示某個語言」的標籤（例如 LocalizedLabel.fixedLanguage）用。
 */
const fixedLanguageMaps: Partial<Record<LanguageCode, Record<string, string>>> = {};
const fixedLanguageLoading: Partial<Record<LanguageCode, Promise<void>>> = {};

/** 不論目前語系為何，固定查詢指定語言的翻譯；該語言尚未載入完成時先回傳 key 本身。 */
export function getLocalizedStringForLanguage(searchKey: string, languageCode: LanguageCode): string {
    return fixedLanguageMaps[languageCode]?.[searchKey] ?? searchKey;
}

/** 載入指定語言的翻譯表並常駐快取，供 getLocalizedStringForLanguage 查詢；同一語言重複呼叫只會實際載入一次。 */
export async function loadFixedLanguage(languageCode: LanguageCode, bundleName = ((globalThis as Record<string, unknown>)['__APP_GAME_ID__'] as string) ?? '1003'): Promise<void> {
    if (fixedLanguageMaps[languageCode]) return;
    if (!fixedLanguageLoading[languageCode]) {
        fixedLanguageLoading[languageCode] = (async () => {
            try {
                const bundle = AppAssetBundle.getInstance(bundleName);
                await bundle.loadBundle();
                const asset = await bundle.loadAsset(`resources/languages/${languageCode}`, JsonAsset);
                fixedLanguageMaps[languageCode] = asset.json as Record<string, string>;
            } catch (e) {
                console.warn(`[i18n] 固定語言載入失敗: ${languageCode}`, e);
            }
        })();
    }
    await fixedLanguageLoading[languageCode];
}

export async function setLocalizedImage(
    sprite: Sprite,
    bundleName: string,
    spriteName: string,
    targetLanguage: string = currentLanguage.get(),
    path: string = ""
): Promise<void> {
    sprite.spriteFrame = null;
    const result = await getLocalizedSpriteFrame(bundleName, spriteName, targetLanguage, path);
    // 在載入中若 node 被销毁，则不再设置 spriteFrame
    if (sprite?.node?.isValid) {
        sprite.spriteFrame = result;
    } else {
        console.warn("Sprite node is not available, cannot set sprite frame.", spriteName);
    }
}

export async function getLocalizedSpriteFrame(
    bundleName: string,
    spriteName: string,
    targetLanguage: string = currentLanguage.get(),
    path: string = ""
): Promise<SpriteFrame> {
    const bundle = await AppAssetBundle.getInstance(bundleName).loadBundle();

    targetLanguage = REVERSE_LANGUAGE_MAP[targetLanguage as LanguageCode] || targetLanguage;
    let i18nImageDirectory = `${path}i18nResource/${targetLanguage}/image`;

    // 如果找不到对应语言的图片目录，则使用默认语言
    if (bundle.getDirWithPath(i18nImageDirectory).length <= 0) {
        if (targetLanguage === "zh-HK" || targetLanguage === "zh-CN") {
            i18nImageDirectory = i18nImageDirectory.split(targetLanguage).join("zh-CN");
        } else {
            i18nImageDirectory = i18nImageDirectory.split(targetLanguage).join("en-US");
        }
    }

    const searchName = `${i18nImageDirectory}/${spriteName}/spriteFrame`;
    return await AppAssetBundle.getInstance(bundleName).loadAsset(searchName, SpriteFrame);
}

/**
 * 语言映射表，将语言-地区码映射到简化的语言代码
 * 例如，将 "zh-CN" 映射到 "zh"
 * 目前所有业务逻辑统一使用2位代码，比如zh、en、vi（因为多语系表是使用2位代码）
 * 资源目录则使用带地区码的完整代码，比如zh-CN、en-US、vi-VN（因为资源目录通常是这样命名的）
 */
const LANGUAGE_MAP = {
    "en-US": "en",
    "zh-CN": "zh",
    "zh-HK": "zh-HK",
    "vi-VN": "vi",
    "id-ID": "id",
    "ja-JP": "ja",
    "ko-KR": "ko",
    "ar-SA": "ar",
    "es-ES": "es",
    "tr-TR": "tr",
    "pt-BR": "pt",
    "ru-RU": "ru",
    "th-TH": "th",
    "da-DK": "da",
    "de-DE": "de",
    "fi-FI": "fi",
    "fr-FR": "fr",
    "it-IT": "it",
    "nl-NL": "nl",
    "no-NO": "no",
    "pl-PL": "pl",
    "ro-RO": "ro",
    "sv-SE": "sv",
    "my-MM": "my",
} as const;

/**
 * 反转 LANGUAGE_MAP 以便通过语言代码获取完整的语言-地区码
 * 例如，将 "zh" 映射回 "zh-CN"
 */
const REVERSE_LANGUAGE_MAP = Object.fromEntries(
    Object.entries(LANGUAGE_MAP).map(([k, v]) => [v, k])
) as Record<LanguageCode, LanguageCodeWithLocale>;

/** 获取语言对应的完整语言-地区码 */
export function getLanguageWithLocale(language: LanguageCode): LanguageCodeWithLocale {
    return REVERSE_LANGUAGE_MAP[language];
}

/** 將語言-地區碼轉為簡化語言碼（不會 set currentLanguage） */
export function resolveLanguageCode(locale: string): LanguageCode {
    return LANGUAGE_MAP[locale as LanguageCodeWithLocale]
        ?? (Object.values(LANGUAGE_MAP).includes(locale as LanguageCode) ? locale as LanguageCode : defaultLanguage);
}

const languageCodeList = Object.values(LANGUAGE_MAP) as LanguageCode[];

export const defaultLanguage = languageCodeList[0];
export const defaultLanguageWithLocale = REVERSE_LANGUAGE_MAP[defaultLanguage];

/** mobx 移除計劃：保留 .get()/.set() 介面，讓現有呼叫端（assets/lobby、assets/Game 等
 *  多個 submodule）不用改寫；.set() 換成明確 emit baseRuntimeEventBus 事件取代 mobx 的
 *  自動依賴追蹤 */
class LanguageBox {
    private value: LanguageCode = defaultLanguage;
    /**
     * 目前的語系。
     *
     * @returns 語系代碼。
     */
    get(): LanguageCode {
        return this.value;
    }
    /**
     * 切換語系並發 LANGUAGE_CHANGED；跟目前相同時直接略過。
     *
     * @param value 語系代碼。
     */
    set(value: LanguageCode): void {
        if (this.value === value) return;
        this.value = value;
        baseRuntimeEventBus.emit(BASE_EVENT_TYPE.LANGUAGE_CHANGED, {
            eventId: BASE_EVENT_ID.LANGUAGE_CHANGED,
            language: value,
        });
    }
}

/**
 * 当前语言, 不带地区码 e.g. zh
 */
export const currentLanguage = new LanguageBox();

/**
 * 当前语言, 带地区码 e.g. zh-CN
 */
export const currentLanguageWithLocale = (): LanguageCodeWithLocale =>
    REVERSE_LANGUAGE_MAP[currentLanguage.get()];

/**
 * 是否为中文语言环境 zh-CN 或 zh-HK 或 zh
 */
export const isChinese = (): boolean => currentLanguage.get().includes("zh");

/**
 * 设置中文语言环境下的数组元素
 * @param array - 需要设置的数组
 * @param cnArray - 中文数组
 */
export const setLanguageArray = <T>(array: T[], cnArray: T[]): void => {
    if (isChinese()) {
        array.forEach((_, index) => {
            array[index] = cnArray[index] ?? array[index];
        });
    }
};

