import { _decorator, Component, Node, Prefab, Label } from 'cc';
import AppUtility from '../../../utils/AppUtility';
import { CURRENCY_MAP, VIEWMAP } from '../../../store/StoreMap';
import StoreManager from '../../../store/StoreManager';
import { getLocalizedString } from '../../../i18n/LanguageData';
import type { BetHistorySummary } from '../../../models/BetHistory';
import type { HistoryView } from './HistoryView';
const { ccclass, property } = _decorator;

@ccclass('1003/HistoryItem')
export class HistoryItem extends Component {
    @property(Node)
    title: Node = null;

    @property(Node)
    itemInfo: Node = null;

    storeManager: StoreManager;
    private isOpen = false;
    private isFirst = true;
    private ID: string = '';
    public historyView: HistoryView = null;
    public titleData: BetHistorySummary = null;
    /**
     * 取得 StoreManager 並把標題列的資料填上去。
     */
    override start() {
        this.storeManager = StoreManager.getInstance();
        this.updateTitleInfo();
    }
    /**
     * 展開或收合這一筆紀錄；第一次展開時才去要明細。
     *
     * @returns 明細載入並填好之後 resolve。
     */
    async onClick() {
        this.isOpen = !this.isOpen;
        this.updateArrow();
        if (this.isOpen) {
            await this.updateItemInfo();
        } else {
            this.itemInfo.active = false;
        }
    }
    /**
     * 載入這一筆的明細並建立盤面節點；之後再展開就直接開節點，不重載。
     *
     * 載入期間會先開 Spinner，載完由 HistoryAdapter 那側關掉。
     *
     * @returns 明細節點掛好之後 resolve。
     */
    async updateItemInfo() {
        if (!this.isFirst) {
            this.itemInfo.active = true;
            return;
        }
        this.isFirst = false;
        this.storeManager.getViewStore().setViewName(VIEWMAP.SPINNERVIEW);
        const node = await this.historyView?.viewModel.createHistoryDetailView(this.ID);
        if (!node) {
            this.isFirst = true;
            this.isOpen = false;
            this.updateArrow();
            this.storeManager.getViewStore().setDeleteViewName('SpinnerView');
            return;
        }

        node.setScale(0, 0, 0);

        this.scheduleOnce(() => {
            this.itemInfo.addChild(node);
            node.setScale(1, 1, 1);
            this.storeManager.getViewStore().setDeleteViewName('SpinnerView');
        }, 0.5);
    }

    /**
     * 依展開狀態把箭頭轉到 0 度或 180 度。
     */
    updateArrow() {
        this.getArrow().angle = this.isOpen ? 180 : 0;
    }
    /**
     * 把這一筆的完整局號複製到剪貼簿，並在標題旁顯示複製成功的 Toast。
     */
    onIDClick() {
        console.log('[HistoryModel] idClick');
        let label = this.title.getChildByName('ID').getComponent(Label);
        navigator.clipboard.writeText(this.ID).then(() => {
            console.log('[HistoryItem] 複製成功:', this.ID);
            this.storeManager.getViewStore().showToast(getLocalizedString('copy.success'), { x: label.node.x, y: label.node.y });
        });
    }

    /**
     * 把局號、日期、餘額、下注與贏分填進標題列。
     */
    updateTitleInfo() {
        this.ID = this.titleData.operationId;
        this.title.getChildByName('ID').getComponent(Label).string = this.formatdId(this.titleData.operationId);
        this.title.getChildByName('Date').getComponent(Label).string = `${AppUtility.formatDateYMD(this.titleData.createdAtMs)}`;
        this.title.getChildByName('Balance').getComponent(Label).string = `${CURRENCY_MAP[this.titleData.currency] ?? this.titleData.currency} ${this.titleData.balanceAfter}`;
        this.title.getChildByName('Bet').getComponent(Label).string = `${this.titleData.betAmount}`;
        this.title.getChildByName('WinAmount').getComponent(Label).string = `${this.titleData.winAmount}`;
    }
    /**
     * 局號太長時只顯示末 7 碼（前面補省略號），避免撐破標題列。
     *
     * @param roundID 完整局號。
     * @returns 縮短後的字串；7 碼以內原樣回傳。
     */
    formatdId(roundID: string) {
        return roundID.length > 7 ? '.....' + roundID.slice(-7) : roundID;
    }
    /**
     * 取得標題列上的展開箭頭節點。
     *
     * @returns 箭頭節點。
     */
    getArrow() {
        return this.title.getChildByName('Arrow');
    }
}
