import { SceneSpeedActivationMode, type SceneSpeedOverride } from '../config/SceneSpeedStore';

// 跟轉輪節奏共用同一份 jsons/reelConfig.json 匯出一份檔案
// speedFactors 是額外欄位 parseReelConfig() 會直接忽略

// 一般不加速，快轉 1.5x、急速轉 2x（取代原本快/急速各自寫死的節奏秒數）
export const DEFAULT_SCENE_SPEED_CONFIG: SceneSpeedOverride = {
    speedFactors: [1, 1.5, 2],
    activationMode: SceneSpeedActivationMode.SPIN_WINDOW,
};

/** 解析 reelConfig.json 裡的整體速度欄位 */
export function parseSceneSpeedConfig(raw: unknown): SceneSpeedOverride {
    const obj = raw as { speedFactors?: unknown; speedActivationMode?: unknown } | null;
    const arr = obj?.speedFactors;
    const activationMode = obj?.speedActivationMode === SceneSpeedActivationMode.GAME_WIDE
        ? SceneSpeedActivationMode.GAME_WIDE
        : SceneSpeedActivationMode.SPIN_WINDOW;

    if (Array.isArray(arr) && arr.length === 3 && arr.every((v) => typeof v === 'number')) {
        return { speedFactors: [arr[0], arr[1], arr[2]], activationMode };
    }

    return { speedFactors: DEFAULT_SCENE_SPEED_CONFIG.speedFactors, activationMode };
}
