import { isGoldenSymbolId } from '../config/SlotGameDefinition';

/** 一欄在一次消除裡要怎麼處理 */
export interface ColumnSettlePlan {
    /** 所有中獎的列：播中獎特效、算飄分（含中獎後翻成 Wild 的金牌） */
    readonly winRows: number[];
    /** 中獎的金牌所在列：原地翻成 Wild，不消除 */
    readonly goldenRows: number[];
    /** 真正要消掉的列＝中獎列扣掉金牌 */
    readonly removedRows: number[];
    /** 補牌後這一欄的可見盤面；這一欄沒有要消的格子（只有金牌翻面或完全沒中獎）時為 null，不需要補牌 */
    readonly toMap: number[] | null;
    /** 從上方補進來的新牌數量 */
    readonly newFillCount: number;
}

/**
 * 算出一欄在一次消除裡的中獎格、金牌、要消的格，以及補牌後的盤面。
 *
 * 中獎格分兩組（GDD 4.2 黃金麻將）：所有中獎格播中獎特效、算飄分；真正要消掉的是中獎格扣掉金牌。
 * 中獎的金牌不消除，翻成 Wild 留在盤面上，跟其他留下來的牌一起往下掉；沒中獎的金牌原樣保留。
 *
 * 補牌公式與 mock 的 `settle()` 一致：新補的牌（下一個 step 該欄頂端 removedRows.length 顆）
 * ＋留下來的牌（用目前盤面的 id 保留身分，避免被下一盤覆蓋成別的符號；中獎金牌換成 Wild）。
 *
 * 刻意不 import `cc`，讓 Node 可以直接拿這支跟 mock 引擎的下一盤比對。
 *
 * @param currentCol 這一欄目前的可見符號 id，由上往下。
 * @param winRowSet 這一欄中獎的列；沒中獎時為 undefined。
 * @param nextCol 下一個 step 這一欄的符號 id，用來取新補的牌；沒有下一個 step 時為 undefined。
 * @param visibleRows 這一欄的可見列數，補牌後的盤面會截到這個長度。
 * @param wildId Wild 的符號 id。
 * @returns 這一欄的處理結果；這一欄完全沒有中獎時為 null。
 */
export function planColumnSettle(currentCol: readonly number[], winRowSet: ReadonlySet<number> | undefined, nextCol: readonly number[] | undefined, visibleRows: number, wildId: number): ColumnSettlePlan | null {
    const winRows: number[] = [];
    for (let row = 0; row < currentCol.length; row++) {
        if (winRowSet?.has(row)) winRows.push(row);
    }
    if (winRows.length === 0) return null;

    const goldenRows = winRows.filter((row) => isGoldenSymbolId(currentCol[row]));
    const removedRows = winRows.filter((row) => !isGoldenSymbolId(currentCol[row]));
    if (removedRows.length === 0) return { winRows, goldenRows, removedRows, toMap: null, newFillCount: 0 };

    const survived = currentCol.flatMap((id, row) => (removedRows.includes(row) ? [] : [goldenRows.includes(row) ? wildId : id]));
    const newFills = nextCol?.slice(0, removedRows.length) ?? [];
    return { winRows, goldenRows, removedRows, toMap: [...newFills, ...survived].slice(0, visibleRows), newFillCount: newFills.length };
}
