import { getVisibleRowsForColumn, type RawSlotGrid, type SlotColumn, type SlotGrid, type SlotGridLayout } from '../models/SlotGrid';

function assertNonNegativeInteger(value: number, field: string): void {
    if (!Number.isInteger(value) || value < 0) {
        throw new RangeError(`${field} must be a non-negative integer, received ${value}`);
    }
}

/** 純資料 decoder：只處理維度、buffer 與 row order，不解析遊戲 Symbol。 */
export class SlotGridDecoder {
    /**
     * 把後端的原始盤面解成前端用的結構，過程中先驗證維度是否相符。
     *
     * @param source 後端回傳的盤面。
     * @param layout 這一局的盤面形狀。
     * @returns 解析後的盤面。
     * @throws 維度對不起來時丟出。
     */
    decode(source: RawSlotGrid, layout: SlotGridLayout): SlotGrid {
        this.validate(source, layout);

        const visibleStart = layout.bufferPlacement === 'start' ? layout.bufferRows : 0;
        const columns: SlotColumn[] = source.cells.map((rawColumn, index) => {
            const visibleEnd = visibleStart + getVisibleRowsForColumn(layout, index);
            const symbolIds = rawColumn.slice(visibleStart, visibleEnd);

            if (layout.sourceRowOrder !== layout.presentationRowOrder) symbolIds.reverse();
            return { index, symbolIds };
        });

        return { layout: { ...layout }, columns };
    }

    /**
     * 驗證原始盤面與 layout 的欄列數是否一致。
     *
     * 對不起來時丟例外而不是默默修正：這種不一致通常代表本地登記的盤面形狀
     * 跟後端不同步，硬解下去會整盤錯位。呼叫端要負責讓 layout 以實際資料為準
     * （見 agent-pitfalls.md 坑 #30）。
     *
     * @param source 後端回傳的盤面。
     * @param layout 這一局的盤面形狀。
     * @throws 欄列數不符或出現負數時丟出。
     */
    private validate(source: RawSlotGrid, layout: SlotGridLayout): void {
        assertNonNegativeInteger(source.columns, 'source.columns');
        assertNonNegativeInteger(source.rows, 'source.rows');
        assertNonNegativeInteger(layout.columns, 'layout.columns');
        assertNonNegativeInteger(layout.visibleRows, 'layout.visibleRows');
        assertNonNegativeInteger(layout.bufferRows, 'layout.bufferRows');

        if (source.columns !== layout.columns || source.cells.length !== source.columns) {
            throw new RangeError(`Grid column count mismatch: source=${source.columns}, cells=${source.cells.length}, layout=${layout.columns}`);
        }
        if (source.rows !== layout.visibleRows + layout.bufferRows) {
            throw new RangeError(`Grid row count mismatch: source=${source.rows}, visible=${layout.visibleRows}, buffer=${layout.bufferRows}`);
        }
        // 不規則輪帶：visibleRows 是各欄的最大值，逐欄值不得超過它，否則 decode 的 slice 會靜默少切符號
        const perColumn = layout.visibleRowsPerColumn;
        if (perColumn) {
            if (perColumn.length !== layout.columns) {
                throw new RangeError(`layout.visibleRowsPerColumn has ${perColumn.length} entries; expected ${layout.columns}`);
            }
            perColumn.forEach((rows, index) => {
                assertNonNegativeInteger(rows, `layout.visibleRowsPerColumn[${index}]`);
                if (rows > layout.visibleRows) {
                    throw new RangeError(`layout.visibleRowsPerColumn[${index}] is ${rows}; must not exceed layout.visibleRows=${layout.visibleRows}`);
                }
            });
        }
        source.cells.forEach((column, index) => {
            if (column.length !== source.rows) {
                throw new RangeError(`Grid column ${index} has ${column.length} rows; expected ${source.rows}`);
            }
        });
    }
}
