import { TemplateView } from './TemplateView';
import { IStatus } from './StatusManager';
import StoreManager from '../../store/StoreManager';
import { tween, UIOpacity, Vec3 } from 'cc';
import { AUTOSPINSTATUSMAP, TURBOSTATUSMAP } from '../../store/StoreMap';
import { getLocalizedString } from '../../i18n/LanguageData';
export default class SpinStartStatus implements IStatus {
    templateView: TemplateView;
    storeManager: StoreManager;
    data: any;
    private spinTween: any;
    /**
     * 注入所屬的操作列與 StoreManager。
     *
     * @param context 這個狀態要操作的操作列。
     * @returns 自己，方便串接呼叫。
     */
    setContext(context: TemplateView) {
        this.templateView = context;
        this.storeManager = StoreManager.getInstance();
        return this;
    }

    /**
     * 暫存這次進入狀態時帶的資料。
     *
     * @param data 狀態資料。
     */
    setData(data: any) {
        this.data = data;
    }
    /**
     * 進入「開始轉動」狀態：鎖掉注額相關按鈕，並處理自動轉的局數遞減。
     *
     * @param data 進入時帶的資料。
     * @returns 處理完之後 resolve。
     */
    async onEnter(data?: any) {
        this.templateView.minusBtn.interactable = false;
        this.templateView.plusBtn.interactable = false;
        this.templateView.selectBetBtn.interactable = false;
        this.spinBtnAction();
        // HK store 才有 setIsUpdate（history cache）；TW 沒這概念，用 optional chain 跳過
        this.storeManager.getHttpClientStore()?.setIsUpdate?.(true);
    }

    /**
     * 依自動轉狀態決定顯示無限標記還是遞減局數。
     *
     * 局數只由 isPrimary 那一份操作列遞減——橫直版兩份都會跑到這裡，
     * 不擋的話一局會被扣兩次。
     */
    spinBtnAction() {
        if (this.storeManager.getGameStore().autoSpinStatus === AUTOSPINSTATUSMAP.ON) {
            if (this.storeManager.getGameStore().autoSpinTimes == 'MAX') {
                this.templateView.setInfiniteVisible(true);
            } else {
                //因為直橫版會扣兩次， 讓他只扣一次
                // isPrimary 由GameSceneViewModel指定
                if (this.templateView.isPrimary) {
                    let currentTimes = this.storeManager.getGameStore().autoSpinTimes;
                    this.storeManager.getGameStore().setAutoSpinTimes(currentTimes - 1);
                }
            }
            this.templateView.setAutoSpinMode(this.getSpeed());
        } else this.templateView.setSpinMode();
    }

    // 動畫控制
    /**
     * 把加速檔位換算成轉輪的時間倍率。
     *
     * @returns 倍率；數字越小轉得越快。
     */
    getSpeed() {
        switch (StoreManager.getInstance().getGameStore().turboStatus) {
            case TURBOSTATUSMAP.NORMAL:
                return 1;
            case TURBOSTATUSMAP.FAST:
                return 0.75;
            case TURBOSTATUSMAP.MAX:
                return 0.5;
            default:
                return 1;
        }
    }

    /**
     * 離開狀態時清掉暫存資料。
     */
    onExit() {
        this.data = null;
    }
}
