import { EventKeyboard, Input, input, KeyCode } from "cc";
import StoreManager from "../store/StoreManager";
import { GAMESTOREMAP } from "../store/StoreMap";
import { SlotMachineState } from "../reel/model/SlotMachineModel";
import { GameStateKey } from "../states/GameStateKey";

/**
 * SpinShortcutController（Space 鍵快捷 spin）
 *
 * 1001/1002 邏輯完全相同。監聽鍵盤 KEY_DOWN，按下 Space 時檢查：非 buy
 * feature/中獎演出/bonus 結果彈窗擋著、不在 FG 狀態、機台為 IDLE，通過才
 * 中止中獎動畫並觸發 spin。
 */
export interface SpinShortcutDeps {
    storeManager: StoreManager;
    getCurStateKey: () => string | null;
    getSlotState: () => SlotMachineState;
    stopWinAnimations: () => void;
}

/** Space 鍵觸發 spin 的鍵盤快捷鍵，1001/1002 邏輯完全相同 */
export class SpinShortcutController {
    /**
     * @param deps 取得 store、狀態與中止演出的依賴。
     */
    constructor(private deps: SpinShortcutDeps) { }

    /**
     * 開始監聽鍵盤，讓空白鍵等同按下 spin。
     */
    bind(): void {
        input.on(Input.EventType.KEY_DOWN, this.onKeyDown, this);
    }

    /**
     * 停止監聽鍵盤。
     */
    unbind(): void {
        input.off(Input.EventType.KEY_DOWN, this.onKeyDown, this);
    }

    /**
     * 檢查目前是不是有彈窗或表演擋著，不該讓快捷鍵觸發 spin。
     *
     * @returns 被擋住時 true。
     */
    private isSpinBlocked(): boolean {
        const store = this.deps.storeManager.getGameStore();
        return store.buyFeatureData != null || store.winAnimationData != null || store.bonusResultData != null;
    }

    private onKeyDown = (event: EventKeyboard): void => {
        if (event.keyCode !== KeyCode.SPACE) return;
        if (this.isSpinBlocked()) return;
        if (this.deps.getCurStateKey() === GameStateKey.FG) return;

        if (this.deps.getSlotState() === SlotMachineState.IDLE) {
            this.deps.stopWinAnimations();
            this.deps.storeManager.getGameStore().setSpinStatus(GAMESTOREMAP.SPIN_START);
        }
    };
}
