import { _decorator, Button, Node } from 'cc';
import { EventComponent } from '../../events/EventComponent';
import { PopupManager } from './PopupStack';
import { PopupProperty } from './PopupProperty';

const { ccclass } = _decorator;

/**
 * PopupBase — 遊戲內彈窗共用基底。
 *
 * 提供關閉鈕／（選配）返回鈕／（選配）背景遮罩點擊關閉這幾個所有彈窗
 * 共通的部分。具體彈窗（AutoPlayPopup／SystemMenuPopup／LeaveConfirmPopup／
 * SeatLobbyPopup）繼承這個類別，把自己的內容掛在 contentRoot 底下，`onLoad()`
 * 記得呼叫 `super.onLoad()` 再接自己的邏輯。
 *
 * 拆圖規格（拆圖備注）裡的四種彈窗共通元素：九宮格背景與標題文字都是 prefab
 * 自己套（程式碼不介入，PopupProperty 也沒有對應欄位），程式碼只處理右上角
 * 關閉鈕；返回鈕跟背景遮罩點擊關閉是選配（AUTO PLAY／系統選單／離開確認沒有
 * 返回鈕，選座位有）。
 */
@ccclass('1003/PopupBase')
export class PopupBase extends EventComponent {
    protected property: PopupProperty | null = null;

    /**
     * 抓到子節點上的 PopupProperty，並綁好關閉鈕、返回鈕與遮罩點擊。
     *
     * 三個節點都是選配，留空時 bindClick() 會直接略過——彈窗少一顆返回鈕
     * 不該讓整個 onLoad 炸掉。子類別覆寫時記得呼叫 super.onLoad()。
     */
    protected override onLoad(): void {
        this.property = this.getComponentInChildren(PopupProperty);

        this.bindClick(this.property?.closeNode, this.close);
        this.bindClick(this.property?.backNode, this.onBackClick);
        this.bindClick(this.property?.maskNode, this.onMaskClick, Node.EventType.TOUCH_END);
    }

    /**
     * 綁定點擊事件並自動在銷毀時解除，取代各彈窗各自手寫的 `on()` + `trackDisposer(off())` 樣板。
     *
     * target 傳 null／undefined 會直接略過（選配節點留空、或 Editor 忘了指定都不會炸），
     * 解除時用的是綁定當下捕捉到的同一個節點，不會因為欄位後來被改掉而解錯對象。
     */
    protected bindClick(target: Node | Button | null | undefined, handler: () => void, eventType: string = Button.EventType.CLICK): void {
        const node = target instanceof Button ? target.node : target;
        if (!node) return;
        node.on(eventType, handler, this);
        this.trackDisposer(() => {
            if (node.isValid) node.off(eventType, handler, this);
        });
    }

    /** 關閉彈窗，交給 PopupManager 統一處理（同步移出堆疊＋銷毀節點）；
     *  要做關閉動畫的彈窗可以覆寫這個方法，動畫播完後仍要呼叫 PopupManager.closeNode(this.node)。
     *  注意 PopupManager.closeTop()／closeAll() 會直接走 closeNode()，不會經過這裡的覆寫版本。 */
    close(): void {
        PopupManager.closeNode(this.node);
    }

    /** 返回鈕預設行為＝關閉；有上一層可以回的彈窗（例如選座位要回選單）覆寫這個 */
    protected onBackClick(): void {
        this.close();
    }

    /** 背景遮罩點擊預設＝關閉；不想讓玩家點外部關閉的彈窗把 maskNode 留空即可，不會呼叫到這裡 */
    protected onMaskClick(): void {
        this.close();
    }

    /**
     * 把自己從彈窗堆疊移除再交回基底。
     *
     * 彈窗可能是被整層一起銷毀的（切場景時掛載層連同底下的彈窗都會消失），
     * 那條路不會經過 close()，不主動移除的話 PopupManager 會殘留失效項目。
     */
    public override onDestroy(): void {
        // 彈窗可能是被整層一起銷毀的（切場景時掛載層連同底下的彈窗都會消失），
        // 這條路沒經過 close()，要主動把自己移出堆疊，否則 PopupManager 會殘留失效項目
        PopupManager.detach(this.node);
        super.onDestroy();
    }
}
