import { _decorator, Component, Node, sp, Vec3 } from 'cc';

const { ccclass, property } = _decorator;

/** 動畫播完後這個節點怎麼處理 */
export type SpineEndAction =
    /** 關掉節點，讓呼叫端（AppSpine）回收進節點池重複使用。預設值 */
    | 'hide'
    /** 直接銷毀，不回收 */
    | 'destroy'
    /** 什麼都不做，留在畫面上維持最後一格 */
    | 'keep';

/** 播放選項，全部可省略 */
export interface SpinePlayOptions {
    /** 是否循環，預設 false。true 時不等結束，setAnimation 之後立刻 resolve */
    loop?: boolean;
    /** 播放倍率，預設 1 */
    timeScale?: number;
    /** 相對父節點的位置，預設 (0, 0, 0) */
    position?: Vec3;
    /** 整體縮放，預設 1 */
    scale?: number;
    /** 播完後怎麼處理這個節點，預設 'hide' */
    onEnd?: SpineEndAction;
    /** 播完時的回呼，在 onEnd 處理之前呼叫 */
    onComplete?: () => void;
}

/** 動畫真的結束後，再多等這麼久才觸發保底收尾（秒），避免跟 complete 事件搶在同一刻 */
const FALLBACK_PADDING = 0.2;

/** 讀不到動畫長度時的保底秒數 */
const FALLBACK_DURATION = 1.5;

/**
 * 一顆可重複使用的 spine 節點：換上指定的 SkeletonData、播一段動畫、結束後收尾。
 *
 * 掛在 `resources/prefabs/SpineNode.prefab` 的根節點上。節點的生成、置頂與回收由
 * {@link AppSpine} 負責，這支只管「這一顆怎麼播、什麼時候算播完」。
 *
 * 邏輯放在 Component 而不是單例，是因為收尾需要 `scheduleOnce` 的保底計時器，
 * 那是 Component 才有的能力，而且節點被銷毀時 Cocos 會自動取消排程。
 */
@ccclass('1003/SpineNode')
export class SpineNode extends Component {
    @property({ type: sp.Skeleton, tooltip: '實際播動畫的 Skeleton' })
    public skeleton: sp.Skeleton = null!;

    @property({ type: Node, tooltip: '美術偏移用的中間層，播放邏輯不會動它（可留空）' })
    public pivot: Node | null = null;

    /**
     * 換上 SkeletonData 並播一段動畫。
     *
     * 收尾同時掛 `setCompleteListener` 與一個 `scheduleOnce` 保底計時器，兩邊都會呼叫同一個
     * 只生效一次的 `finish()`。**保底不是可有可無的**：complete 事件在動畫名稱不存在、資產換到
     * 一半、或節點中途被關掉時都可能不來，少了它這個 Promise 就永遠不 settle，`await` 它的
     * 整條流程會無聲吊死（agent-pitfalls.md 坑 #34）。
     *
     * @param data 要換上的骨架資料。
     * @param anim 動畫名稱，必須是該資產真的有的名字。
     * @param opt 播放選項，見 {@link SpinePlayOptions}。
     * @returns 一次性動畫回傳「播完並收尾後」resolve 的 Promise；`loop: true` 時立刻 resolve。
     */
    public play(data: sp.SkeletonData, anim: string, opt: SpinePlayOptions = {}): Promise<void> {
        const loop = opt.loop ?? false;
        const timeScale = opt.timeScale ?? 1;

        this.node.active = true;
        this.node.setPosition(opt.position ?? Vec3.ZERO);
        const scale = opt.scale ?? 1;
        this.node.setScale(scale, scale, 1);

        if (!this.skeleton) {
            console.warn('[SpineNode] 沒接 skeleton，prefab 根節點的元件欄位要指到 Skeleton 子節點上的 sp.Skeleton');
            return Promise.resolve();
        }

        // 換資產前先把上一次的軌道清掉，否則殘留的 track 會跟新動畫混在一起
        this.skeleton.clearTracks();
        this.skeleton.setCompleteListener(null!);
        this.skeleton.skeletonData = data;
        this.skeleton.timeScale = timeScale;
        this.skeleton.node.active = true;

        const entry = this.skeleton.setAnimation(0, anim, loop);
        if (!entry) {
            console.warn(`[SpineNode] 資產裡沒有動畫 ${anim}，略過播放`);
            this.applyEndAction(opt.onEnd ?? 'hide');
            return Promise.resolve();
        }

        if (loop) {
            // 循環動畫沒有「播完」這回事，交由呼叫端自己決定何時停
            return Promise.resolve();
        }

        return new Promise<void>((resolve) => {
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;

                if (this.skeleton?.isValid) this.skeleton.setCompleteListener(null!);
                opt.onComplete?.();
                this.applyEndAction(opt.onEnd ?? 'hide');
                resolve();
            };

            this.skeleton.setCompleteListener((trackEntry) => {
                if (trackEntry.trackIndex === 0) finish();
            });

            const duration = entry.animation?.duration ?? FALLBACK_DURATION;
            this.scheduleOnce(finish, (duration + FALLBACK_PADDING) / timeScale);
        });
    }

    /**
     * 停掉目前的動畫並收尾，用在循環動畫或中途取消。
     *
     * @param action 要怎麼處理節點，預設 'hide'。
     */
    public stop(action: SpineEndAction = 'hide'): void {
        if (this.skeleton?.isValid) {
            this.skeleton.setCompleteListener(null!);
            this.skeleton.clearTracks();
        }
        this.applyEndAction(action);
    }

    /**
     * 依收尾方式處理節點本身。
     *
     * @param action 收尾方式。
     */
    private applyEndAction(action: SpineEndAction): void {
        if (!this.node?.isValid) return;

        if (action === 'destroy') {
            this.node.destroy();
            return;
        }
        if (action === 'hide') {
            this.node.active = false;
        }
    }
}
