import { assetManager, Node, sp } from 'cc';
import AppViewPool from './AppViewPool';
import GameConfigManager from '../config/GameConfigManager';
import { SPINE_ASSET_MAP, type SpineKey } from './SpineAssetMap';
import { SpineNode, type SpinePlayOptions } from './SpineNode';

/**
 * SpineNode 的 prefab 路徑，同時是節點池的鍵。
 *
 * 這種用字面字串取資產的寫法不在 import 圖也不在 uuid 圖上，搬 bundle 時靜態分析抓不到
 * （agent-pitfalls.md 坑 #26），所以集中成一個常數，不要散在各呼叫端。
 */
const SPINE_NODE_PREFAB = 'resources/prefabs/SpineNode';

/**
 * 一次性 spine 特效的全域入口。
 *
 * 負責「生成、置頂、回收」，單顆怎麼播交給節點上的 {@link SpineNode}。典型用法：
 *
 * ```ts
 * await AppSpine.getInstance().play(someNode, 'frame_light/frame_light', 'animation');
 * ```
 *
 * 節點走 {@link AppViewPool} 的節點池重複使用，SkeletonData 在這裡做記憶體快取，
 * 同一支資產不會重複載。
 *
 * **適用範圍是新的一次性特效。**已經掛在 prefab 上的固定 spine（寶箱、win 動畫、符號）
 * 各自有自己的狀態管理，不要改走這裡。
 */
export default class AppSpine {
    private static instance: AppSpine;

    private readonly dataCache = new Map<SpineKey, sp.SkeletonData>();

    /**
     * 取得單例，第一次呼叫時才建立。
     *
     * @returns 單例。
     */
    public static getInstance(): AppSpine {
        if (!AppSpine.instance) {
            AppSpine.instance = new AppSpine();
        }
        return AppSpine.instance;
    }

    /**
     * 在指定父節點的最上層生成一顆 spine、播一次動畫，播完依 `onEnd` 收尾。
     *
     * @param parent 要掛在誰底下。
     * @param key spine 資產代號，見 {@link SPINE_ASSET_MAP}。
     * @param anim 動畫名稱。
     * @param opt 播放選項，見 {@link SpinePlayOptions}；`onEnd` 預設 'hide'，會回收進節點池。
     * @returns 播完並收尾後 resolve。任何一步失敗都會印一行 warn 後正常 resolve，不會卡住呼叫端。
     */
    public async play(parent: Node, key: SpineKey, anim: string, opt: SpinePlayOptions = {}): Promise<void> {
        const acquired = await this.acquire(parent, key);
        if (!acquired) return;

        await acquired.comp.play(acquired.data, anim, opt);
        if ((opt.onEnd ?? 'hide') === 'hide') this.recycle(acquired.comp);
    }

    /**
     * 同 {@link play}，但立刻回傳節點本身、不等播完。
     *
     * 循環動畫（`opt.loop = true`）只能用這支——`play()` 對 loop 會馬上 resolve，
     * 呼叫端拿不到任何東西就沒辦法叫它停。拿到之後用 `comp.stop()` 收掉。
     *
     * @param parent 要掛在誰底下。
     * @param key spine 資產代號。
     * @param anim 動畫名稱。
     * @param opt 播放選項。
     * @returns 那顆節點上的 SpineNode；生成失敗時回 null。
     */
    public async spawn(
        parent: Node,
        key: SpineKey,
        anim: string,
        opt: SpinePlayOptions = {}
    ): Promise<SpineNode | null> {
        const acquired = await this.acquire(parent, key);
        if (!acquired) return null;

        const { comp, data } = acquired;
        void comp.play(data, anim, opt).then(() => {
            if ((opt.onEnd ?? 'hide') === 'hide') this.recycle(comp);
        });
        return comp;
    }

    /**
     * 把節點關掉放回節點池。已經被銷毀的節點會直接略過。
     *
     * @param comp 要回收的 SpineNode。
     */
    public recycle(comp: SpineNode): void {
        if (!comp?.node?.isValid) return;
        AppViewPool.getInstance().put(SPINE_NODE_PREFAB, comp.node);
    }

    /**
     * 取一顆節點、掛到父節點最上層，並把資產準備好。
     *
     * @param parent 要掛在誰底下。
     * @param key spine 資產代號。
     * @returns 節點上的元件與骨架資料；任一步失敗時回 null（已經印過 warn）。
     */
    private async acquire(parent: Node, key: SpineKey): Promise<{ comp: SpineNode; data: sp.SkeletonData } | null> {
        if (!parent?.isValid) {
            console.warn(`[AppSpine] 父節點無效，略過 ${key}`);
            return null;
        }

        const data = await this.loadData(key);
        if (!data) return null;

        // 載入是非同步的，這段期間父節點可能已經被銷毀（例如彈窗關掉了）
        if (!parent.isValid) {
            console.warn(`[AppSpine] 載入 ${key} 期間父節點已被銷毀，略過`);
            return null;
        }

        const node = await AppViewPool.getInstance().getView(SPINE_NODE_PREFAB, GameConfigManager.GAMEID);
        if (!parent.isValid) {
            node.destroy();
            return null;
        }

        const comp = node.getComponent(SpineNode);
        if (!comp) {
            console.warn('[AppSpine] SpineNode.prefab 根節點沒掛 SpineNode 元件');
            node.destroy();
            return null;
        }

        parent.addChild(node);
        // addChild 本來就會排到最後（= 最上層），明寫一次是為了池子回收再利用時也保證置頂
        node.setSiblingIndex(parent.children.length - 1);

        return { comp, data };
    }

    /**
     * 依代號載入 SkeletonData，載過的直接給快取。
     *
     * @param key spine 資產代號。
     * @returns 骨架資料；代號不存在或載入失敗時回 null。
     */
    private async loadData(key: SpineKey): Promise<sp.SkeletonData | null> {
        const cached = this.dataCache.get(key);
        if (cached) return cached;

        const uuid = SPINE_ASSET_MAP[key];
        if (!uuid) {
            console.warn(`[AppSpine] SPINE_ASSET_MAP 裡沒有 ${key}`);
            return null;
        }

        return new Promise<sp.SkeletonData | null>((resolve) => {
            assetManager.loadAny({ uuid }, (err: Error | null, asset: sp.SkeletonData) => {
                if (err || !asset) {
                    console.warn(`[AppSpine] 載入 ${key} 失敗`, err);
                    resolve(null);
                    return;
                }
                this.dataCache.set(key, asset);
                resolve(asset);
            });
        });
    }
}
