import { GAME_EVENT_ID, GAME_EVENT_TYPE, gameRuntimeEventBus } from "../events/GameRuntimeEventBus";

export default class TrackerStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/TrackerStore') */
    public readonly $modelType = 'store/TrackerStore';

    private _totalWin = 0;
    /**
     * 本次遊戲累計贏分，埋點用。
     *
     * @returns 累計贏分。
     */
    get totalWin(): number { return this._totalWin; }
    /**
     * 更新累計贏分。
     *
     * @param totalWin 累計贏分。
     */
    setTotalWin(totalWin: number): void { this._totalWin = totalWin; }

    private _totalBet = 0;
    /**
     * 本次遊戲累計下注，埋點用。
     *
     * @returns 累計下注。
     */
    get totalBet(): number { return this._totalBet; }
    /**
     * 更新累計下注。
     *
     * @param totalBet 累計下注。
     */
    setTotalBet(totalBet: number): void { this._totalBet = totalBet; }

    private _playTimes = 0;
    /**
     * 本次遊戲已經轉了幾局，埋點用。
     *
     * @returns 局數。
     */
    get playTimes(): number { return this._playTimes; }
    /**
     * 更新已轉局數。
     *
     * @param playTimes 局數。
     */
    setPlayTimes(playTimes: number): void { this._playTimes = playTimes; }

    private _visualLevel = 0;
    /**
     * 後端給的玩家分級，埋點分桶用。
     *
     * @returns 分級。
     */
    get visualLevel(): number { return this._visualLevel; }
    /**
     * 更新玩家分級。
     *
     * @param visualLevel 分級。
     */
    setVisualLevel(visualLevel: number): void { this._visualLevel = visualLevel; }

    private _visualBalance = 0;
    /**
     * 進場當下的餘額，埋點分桶用。
     *
     * @returns 餘額。
     */
    get visualBalance(): number { return this._visualBalance; }
    /**
     * 更新進場餘額。
     *
     * @param visualBalance 餘額。
     */
    setVisualBalance(visualBalance: number): void { this._visualBalance = visualBalance; }

    private _groupType = '';
    /**
     * AB 測試的分組代碼。
     *
     * @returns 分組代碼；還沒拿到時是空字串。
     */
    get groupType(): string { return this._groupType; }
    /**
     * 更新 AB 分組並發 GROUP_TYPE_CHANGED。
     *
     * 這是這支 store 裡唯一會發事件的 setter——其餘都是純累計數字，沒有人需要即時反應。
     *
     * @param groupType 分組代碼。
     */
    setGroupType(groupType: string): void {
        this._groupType = groupType;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GROUP_TYPE_CHANGED, {
            eventId: GAME_EVENT_ID.GROUP_TYPE_CHANGED,
            groupType,
        });
    }

    app: any;

    /** 保留建構子參數是為了相容 StoreManager 裡 `new TrackerStore({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}
}
