import { _decorator, Component, screen, Size, UITransform, Vec3, view } from 'cc';

const { ccclass } = _decorator;

@ccclass('1003/AdapterNode')
export class AdapterNode extends Component {
    /**
     * 先套一次目前的視窗尺寸，並監聽之後的視窗與解析度變化。
     */
    protected override onLoad(): void {
        super.onLoad?.();
        this.onWindowResize();

        screen.on('window-resize', this.onWindowResize, this);
        view.on('design-resolution-changed', this.onWindowResize, this);
    }

    /**
     * 解除視窗與解析度變化的監聽。
     */
    protected override onDestroy(): void {
        screen.off('window-resize', this.onWindowResize, this);
        view.off('design-resolution-changed', this.onWindowResize, this);
        super.onDestroy?.();
    }

    /**
     * 依實際視窗與設計解析度的比例調整節點縮放，讓節點鋪滿整個畫面（超出部分裁切）。
     *
     * 取「填滿高度」與「填滿寬度」兩個縮放的較大值，所以不會留黑邊、但邊緣會被裁掉——
     * 適合背景這類要蓋滿畫面的節點。要內容完整可見（可能留黑邊）得改取較小值。
     *
     * 算出來的是「在設計解析度座標下」要的縮放，寫進本地 scale 前會除掉父節點鏈的
     * worldScale，所以掛在有縮放的父節點底下（例如 GameViewH 設 0.5）也一樣鋪滿。
     * 只在 onLoad 與視窗／解析度變更時重算——執行中改父節點縮放不會跟著更新。
     */
    private onWindowResize(): void {
        const nodeSize = this.node.getComponent(UITransform)!.contentSize;
        const designResolution = view.getDesignResolutionSize();

        const frameSize = this.getFrameSize();
        const visibleSizeInPixel = view.getVisibleSizeInPixel();

        const scaleHeightToFrameRatio = (frameSize.height * screen.devicePixelRatio) / visibleSizeInPixel.height;
        const scaleHeightToCanvasRatio = designResolution.height / nodeSize.height;
        const scaleToFitHeight = scaleHeightToCanvasRatio * scaleHeightToFrameRatio;

        const scaleWidthToFrameRatio = (frameSize.width * screen.devicePixelRatio) / visibleSizeInPixel.width;
        const scaleWidthToCanvasRatio = designResolution.width / nodeSize.width;
        const scaleToFitWidth = scaleWidthToCanvasRatio * scaleWidthToFrameRatio;

        let scale = Math.max(scaleToFitHeight, scaleToFitWidth);

        // 橫版超寬畫面時
        if (frameSize.width > frameSize.height) {
            const frameAspect = frameSize.width / frameSize.height;
            const designAspect = designResolution.width / designResolution.height;

            if (frameAspect > designAspect) {
                const targetWidth = designResolution.height * frameAspect;
                scale = targetWidth / nodeSize.width;
            }
        }

        // setScale 設的是本地 scale，上面算出來的是「在設計解析度座標下」要的大小，
        // 父節點鏈有縮放（例如 GameViewH 設 0.5）就要除回去，否則背景會跟著縮小、露出黑邊
        const parentScale = this.node.parent?.worldScale ?? Vec3.ONE;
        if (parentScale.x === 0 || parentScale.y === 0) {
            console.warn(`[AdapterNode] ${this.node.name} 的父節點縮放為 0，略過這次適配`);
            return;
        }
        this.node.setScale(scale / parentScale.x, scale / parentScale.y);
    }

    /**
     * 取得以 CSS 像素計的視窗尺寸（把 devicePixelRatio 除掉）。
     *
     * 不除掉 DPR 的話高解析螢幕上算出來的比例會整個偏掉。
     *
     * @returns CSS 像素的視窗尺寸。
     */
    private getFrameSize(): Size {
        const dpr = screen.devicePixelRatio;
        const sizeInCssPixels = screen.windowSize;

        sizeInCssPixels.width /= dpr;
        sizeInCssPixels.height /= dpr;

        return sizeInCssPixels;
    }
}
