import { _decorator, Asset, Component, Label, Node, ProgressBar, sys } from 'cc';
import GameConfigManager from '../config/GameConfigManager';
import { NativeBundleUpdater, NativeUpdateResult } from './NativeBundleUpdater';

const { ccclass, property } = _decorator;
const RESTART_STORAGE_KEY = 'pending_game_entry_for_restart';

/**
 * 掛在 1002 Loading 節點的原生熱更新元件。
 * Web／Editor Preview 不執行；Native 更新成功會保存進場資訊並重啟。
 */
@ccclass('1003/NativeBundleUpdateView')
export class NativeBundleUpdateView extends Component {
    @property(Asset)
    public projectManifest: Asset = null!;

    @property({ type: Node, tooltip: '只有實際下載更新時才顯示的 NativeUpdatePanel' })
    public updatePanel: Node | null = null;

    @property(ProgressBar)
    public progressBar: ProgressBar | null = null;

    @property(Label)
    public progressLabel: Label | null = null;

    @property(Label)
    public statusLabel: Label | null = null;

    private running: Promise<void> | null = null;

    /**
     * 要更新的 bundle 名稱，跟目前的遊戲代號一致。
     *
     * @returns bundle 名稱。
     */
    private get bundleName(): string {
        return GameConfigManager.GAMEID;
    }

    /**
     * 先把更新面板關起來，真的要更新時才開。
     */
    protected override onLoad(): void {
        this.setPanelActive(false);
    }

    /**
     * 確保原生熱更新跑完。非原生平台直接返回；重複呼叫共用同一個 promise。
     *
     * @returns 更新流程結束之後 resolve。已經安排重啟時**永遠不會 resolve**，
     *          這是刻意的，避免 GameRoot 繼續用舊版初始化。
     */
    public ensureUpdated(): Promise<void> {
        if (!sys.isNative) return Promise.resolve();
        if (this.running) return this.running;
        this.running = this.run();
        return this.running;
    }

    /**
     * 實際的更新流程：檢查、下載、回報進度，完成後由 updater 安排重啟。
     *
     * 沒有在 Inspector 指定 project.manifest 時只印 warn 就跳過——
     * 沒設定屬於打包疏漏，但不該讓玩家連遊戲都進不去。
     *
     * @returns 流程結束之後 resolve；已安排重啟時不 resolve。
     */
    private async run(): Promise<void> {
        if (!this.projectManifest) {
            console.warn('[NativeBundleUpdateView] project.manifest 尚未在 Inspector 指定，略過更新');
            return;
        }

        const updater = this.node.getComponent(NativeBundleUpdater) ?? this.node.addComponent(NativeBundleUpdater);
        updater.projectManifest = this.projectManifest;
        NativeBundleUpdater.finishInterruptedUpdate(this.bundleName);
        updater.onProgress = (percent) => {
            this.setPanelActive(true);
            this.setStatus('下載更新中...');
            this.updateProgress(percent);
        };

        this.setStatus('檢查更新中...');
        this.updateProgress(0);

        try {
            const pending = {
                bundle: this.bundleName,
                scene: this.bundleName,
                launchContext: GameConfigManager.launchContext,
            };
            sys.localStorage.setItem(RESTART_STORAGE_KEY, JSON.stringify(pending));

            const result = await updater.checkAndUpdate();
            if (result === NativeUpdateResult.UpToDate) {
                sys.localStorage.removeItem(RESTART_STORAGE_KEY);
                this.setPanelActive(false);
                return;
            }

            // UPDATE_FINISHED 已安排 game.restart；不要讓 GameRoot 繼續初始化舊版。
            await new Promise<void>(() => {});
        } catch (err) {
            sys.localStorage.removeItem(RESTART_STORAGE_KEY);
            console.warn('[NativeBundleUpdateView] 原生熱更新失敗，沿用內建版本', err);
            this.setPanelActive(false);
        } finally {
            updater.onProgress = null;
        }
    }

    /**
     * 開關更新面板。
     *
     * @param active 要開還是要關。
     */
    private setPanelActive(active: boolean): void {
        if (this.updatePanel?.isValid) this.updatePanel.active = active;
    }

    /**
     * 更新面板上的狀態文字。
     *
     * @param text 狀態文字。
     */
    private setStatus(text: string): void {
        if (this.statusLabel) this.statusLabel.string = text;
    }

    /**
     * 更新進度條與百分比文字，值會夾在 0～1 之間。
     *
     * @param percent 進度（0～1）；非有限數字視為 0。
     */
    private updateProgress(percent: number): void {
        const ratio = Math.max(0, Math.min(1, Number.isFinite(percent) ? percent : 0));
        if (this.progressBar) this.progressBar.progress = ratio;
        if (this.progressLabel) this.progressLabel.string = `${Math.ceil(ratio * 100)}%`;
    }
}
