import { ORIENTATION, VIEWMAP } from "./StoreMap";
import { NodePool, find } from "cc";
import {
    GAME_EVENT_ID,
    GAME_EVENT_TYPE,
    gameRuntimeEventBus,
} from "../events/GameRuntimeEventBus";

export default class ViewStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/ViewStore') */
    public readonly $modelType = 'store/ViewStore';

    private _viewName: any | '' = '';
    /**
     * 目前要開的一般 view。
     *
     * @returns VIEWMAP 的項目；沒有時是空字串。
     */
    get viewName(): any | '' { return this._viewName; }
    /**
     * 指定要開哪個 view 並發 VIEW_NAME_CHANGED，由 GameRoot 實際載入並掛上節點。
     *
     * 這裡只是「登記要開什麼」，載入是非同步、在別的地方進行的——
     * 載入途中出錯不會回到呼叫端（見 agent-pitfalls.md 坑 #34）。
     *
     * @param viewName VIEWMAP 的項目。
     */
    setViewName(viewName: any | ''): void {
        this._viewName = viewName;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.VIEW_NAME_CHANGED, {
            eventId: GAME_EVENT_ID.VIEW_NAME_CHANGED,
            viewName,
        });
    }

    private _gameViewName: any = '';
    /**
     * 目前要開的遊戲層 view。
     *
     * @returns GAMEVIEWMAP 的項目。
     */
    get gameViewName(): any { return this._gameViewName; }
    /**
     * 指定要開哪個遊戲層 view 並發 GAME_VIEW_NAME_CHANGED。同 setViewName() 的非同步注意事項。
     *
     * @param gameViewName GAMEVIEWMAP 的項目。
     */
    setGameViewName(gameViewName: any): void {
        this._gameViewName = gameViewName;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GAME_VIEW_NAME_CHANGED, {
            eventId: GAME_EVENT_ID.GAME_VIEW_NAME_CHANGED,
            gameViewName,
        });
    }

    private _alertInfo: Object = { tittle: null, message: null, callback: null };
    /**
     * 下一個彈窗要顯示的標題、內容與回呼。
     *
     * @returns 彈窗資料。
     */
    get alertInfo(): Object { return this._alertInfo; }
    /**
     * 寫入彈窗資料。不發事件——彈窗開啟是由 setViewName() 觸發的，這裡只是先把內容放好。
     *
     * @param alertInfo 標題、內容與回呼。
     */
    setAlertInfo(alertInfo: Object): void { this._alertInfo = alertInfo; }

    private _deleteViewName: string = '';
    /**
     * 要移除的 view 節點名稱。
     *
     * @returns 節點名稱；沒有時是空字串。
     */
    get deleteViewName(): string { return this._deleteViewName; }
    /**
     * 指定要移除哪個 view 並發 DELETE_VIEW_NAME_CHANGED。
     *
     * GameRoot 移除完之後會再呼叫一次傳空字串把它清掉，
     * 不然同一個名稱連續要求移除兩次時第二次不會觸發。
     *
     * @param deleteViewName 節點名稱；傳空字串代表清掉。
     */
    setDeleteViewName(deleteViewName: string): void {
        this._deleteViewName = deleteViewName;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.DELETE_VIEW_NAME_CHANGED, {
            eventId: GAME_EVENT_ID.DELETE_VIEW_NAME_CHANGED,
            deleteViewName,
        });
    }

    NodePool: NodePool

    /** 保留建構子參數是為了相容 StoreManager 裡 `new ViewStore({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {
    }

    showAlertView(title: string, message: string, callback?: () => void) {
        console.log("[ViewStore] showAlertView:", title, message);
        this.setAlertInfo({ tittle: title, message: message, callback: callback });
        this.setViewName(VIEWMAP.ALERTVIEW);
        //
    }

    showStoreAlertView(title: string, message: string, callback?: () => void) {
        console.log("[ViewStore] showStoreAlertView:", title, message);
        this.setAlertInfo({ tittle: title, message: message, callback: callback });
        this.setViewName(VIEWMAP.STOREALERTVIEW);

    }
    /**
     * 顯示一則 Toast。
     *
     * @param message 內容。
     */
    showToast(message: string) {
        console.log("[ViewStore] showToast:", message);
        this.setAlertInfo({ tittle: null, message: message, callback: null });
        this.setViewName(VIEWMAP.TOASTVIEW);
    }
    /**
     * 開啟選注彈窗，並先把場上殘留的橫直版兩份都移掉。
     *
     * 先移除是因為橫直版切換時兩份可能同時存在，直接開會疊在一起。
     *
     * @param orientation 目前方向，決定要開橫版還是直版那一份。
     */
    selectBetView(orientation) {
        const node = find('Canvas/SelectBetView');
        const nodeH = find('Canvas/SelectBetViewH');
        if (node) node.removeFromParent();
        if (nodeH) nodeH.removeFromParent();
        if (orientation == ORIENTATION.LANDSCAPE)
            this.setViewName(VIEWMAP.SELECTBETVIEW);
        else this.setViewName(VIEWMAP.SELECTBETVIEWH);
    }
}
