import { _decorator, Node, Layout, Button, Label, Sprite, SpriteFrame, UIOpacity, Vec3, tween, EffectAsset, Material, Tween, sp } from 'cc';
import TemplateViewModel from './TemplateViewModel';
import { EventComponent } from '../../events/EventComponent';
import type { TypedEventBus } from '../../events/TypedEventBus';
import StoreManager from '../../store/StoreManager';
import AppAssetBundle from '../../utils/AppAssetBundle';
import { GameStateKey } from '../../states/GameStateKey';
import GameConfigManager from '../../config/GameConfigManager';
import AppAnimation from '../AppAnimation';
import { FG_RETRIGGER_BOUNCE } from '../../config/GameConst';
const { ccclass, property } = _decorator;

/**
 * TemplateView（巨亨麻將的下方操作列 View）
 *
 * 原本是 TemplateViewBase（共用基底）＋ TemplateView（1003 覆寫）兩層。獨立成 bundle 之後
 * 沒有跨遊戲共用的必要，依 1001 定稿基線合併成這一支，8 個覆寫直接就地取代基底的版本。
 *
 * ccclass 末尾加 gameId（`TemplateView_1003`）是這個專案的既定隔離做法，比照
 * `1001/TemplateView_1001`、`1002/TemplateView_1002`——entry 仍存在同名的 TemplateView 類別。
 */
@ccclass('1003/TemplateView_1003')
export class TemplateView extends EventComponent {
    /**
     * 訂閱事件匯流排，元件銷毀時自動解除。
     *
     * `EventComponent.subscribeEvent` 是 protected，這裡轉一層 public 供 TemplateViewModel 呼叫。
     *
     * @param bus 目標事件匯流排。
     * @param type 事件類型。
     * @param handler 收到事件時呼叫。
     */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(bus: TypedEventBus<TEvents>, type: K, handler: (payload: TEvents[K]) => void): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Layout)
    betFrame: Layout = null;
    @property(Layout)
    winFrame: Layout = null;
    @property(Layout)
    userFrame: Layout = null;
    @property(Layout)
    spinFrame: Layout = null;
    @property(Layout)
    lockView: Layout = null;

    @property(Button)
    spinBtn: Button = null;
    @property(Button)
    turboBtn: Button = null;
    @property(Button)
    minusBtn: Button = null;
    @property(Button)
    plusBtn: Button = null;
    @property(Button)
    selectBetBtn: Button = null;

    //spriteFrame
    @property(Node)
    spinArrowSprite: Node = null;
    @property(Node)
    spinStopSprite: Node = null;
    @property(Node)
    autoArrowSprite: Node = null;
    @property(Node)
    autoSpinStatus: Node = null;
    @property(Node)
    shopBtn: Node = null;

    @property(sp.Skeleton)
    spinBtnSpine: sp.Skeleton = null;

    @property(Label)
    versionLabel: Label = null;

    /**
     * 場景裡同時存在橫/直版兩個 TemplateView 實例 SpinStartStatus 靠這個判斷負責扣 AutoSpin 局數
     * 在建立橫版那個實例時設為 true 直版維持預設 false 不要用節點
     */
    public isPrimary: boolean = false;

    viewModel: TemplateViewModel;
    protected spinTween: any;
    protected autoSpinTween: any;
    private spinSweepTween: Tween<{ p: number }> | null = null;
    assetBundle: AppAssetBundle;

    /**
     * 基底宣告了 start()，這裡刻意留空——所有初始化都在 onLoad() 完成。
     */
    protected override start(): void {}

    /** 抓好 FG 計數節點並預載暫停鈕圖示。 */
    protected override onLoad(): void {
        this.init();
        this.assetBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        this.viewModel = new TemplateViewModel(this);
        this.viewModel.initial();
        this.setupSpinSweep();
        this.spinBtnSpine?.clearTracks();
        // FG_ROUND_CHANGED 才會發
        this.updateFgRound?.(0, 0);
        this.assetBundle.getSpriteFrame('main_btn_pause').then((frame) => {
            this._pauseIconSpriteFrame = frame;
        });
    }

    /**
     * 替 spin 箭頭掛上掃光材質，並開一個無限循環的掃光 tween。
     *
     * 整段包在 try/catch 裡：shader 是純裝飾，載不到不該讓 onLoad() 中斷，
     * 但失敗一定要留下帶前綴的 warn，不然只會看到「按鈕不會發光」查不出原因。
     *
     * @returns 材質掛好、tween 起跑之後 resolve；中途失敗也是 resolve。
     */
    protected async setupSpinSweep(): Promise<void> {
        try {
            const sprite = this.spinArrowSprite?.getComponent(Sprite);
            if (!sprite) {
                console.warn('[TemplateView] spinArrowSprite 沒有 Sprite 元件，略過掃光效果');
                return;
            }

            const bundle = await this.assetBundle.loadBundle();
            if (!sprite.isValid) return;

            const effect = await new Promise<EffectAsset>((resolve, reject) => {
                bundle.load('resources/shaders/sprite-sweep', EffectAsset, (err, asset) => {
                    if (err) reject(err);
                    else resolve(asset as EffectAsset);
                });
            });
            if (!sprite.isValid) return;

            const material = new Material();
            material.initialize({ effectAsset: effect });
            sprite.customMaterial = material;

            const matInstance = sprite.getMaterialInstance(0);
            if (!matInstance) return;

            // 掃一次（1 秒）之後停 1.5 秒，整段無限重複
            const state = { p: 0 };
            const sweepOpts = { easing: 'cubicOut' as const, onUpdate: () => matInstance.setProperty('sweepProgress', state.p) };
            const oneSweep = tween(state).set({ p: 0 }).to(1.0, { p: 1.0 }, sweepOpts).delay(1.5);

            this.spinSweepTween = tween(state).repeatForever(oneSweep).start();
        } catch (e) {
            console.warn('[TemplateView] spin 掃光材質掛載失敗，按鈕不會發光', e);
        }
    }

    /**
     * 停掉掃光 tween 再交回基底，避免節點銷毀後 tween 還在寫材質參數。
     */
    override onDestroy(): void {
        if (this.spinSweepTween) {
            this.spinSweepTween.stop();
            this.spinSweepTween = null;
        }
        super.onDestroy?.();
    }

    // ******************** Button Click  ************************
    /**
     * spin 鈕。播按鈕 spine 之後把實際邏輯交給 ViewModel。
     */
    spinClick() {
        this.playSpinBtnSpine();
        this.viewModel.spinClick();
    }

    /**
     * 播 spin 鈕上的按壓 spine；沒掛 spine 就什麼都不做。
     */
    private playSpinBtnSpine(): void {
        if (!this.spinBtnSpine) return;
        this.spinBtnSpine.setAnimation(0, 'animation', false);
    }
    /**
     * 選單鈕，轉給 ViewModel。
     */
    menuClick() {
        this.viewModel.menuClick();
    }
    /**
     * 自動轉鈕，轉給 ViewModel。
     */
    autoClick() {
        this.viewModel.autoClick();
    }
    /**
     * 加速鈕，轉給 ViewModel。
     */
    turboClick() {
        this.viewModel.turboClick();
    }
    /**
     * 減注鈕，轉給 ViewModel。
     */
    minusClick() {
        this.viewModel.minusClick();
    }
    /**
     * 加注鈕，轉給 ViewModel。
     */
    plusClick() {
        this.viewModel.plusClick();
    }

    /**
     * 選注鈕，轉給 ViewModel。
     */
    selectBetClick() {
        this.viewModel.selectBetClick();
    }

    /**
     * 商店鈕，轉給 ViewModel。
     */
    storeClick() {
        this.viewModel.storeClick();
    }

    // ******************** 更新 UI  ************************
    /**
     * 更新自動轉剩餘次數的數字，補零成兩位數。
     *
     * @param times 剩餘次數。
     */
    updateAutoSpinTimes(times) {
        this.autoSpinStatus.getChildByName('AutoTimes').getComponent(Label).string = `${String(times).padStart(2, '0')}`;
    }

    // FG 局數倒數 覆寫
    /**
     * 更新免費局的局數顯示；是再觸發加局造成的變動時，順便播放大彈回的演出。
     *
     * @param remaining 剩餘局數。
     * @param total 總局數。
     * @param awarded 這次加上來的局數（GDD 4.3）；大於 0 才播演出，一般倒數不播。
     */
    updateFgRound(remaining: number, total: number, awarded: number = 0): void {
        const counterNode = this.FGCounter;
        if (!counterNode) return;
        const visible = total > 0 && remaining > 0;
        counterNode.active = visible;
        if (!visible) return;
        counterNode.getComponent(Label).string = `${String(remaining).padStart(2, '0')}`;
        // 數字先跳到加完的局數，再放大彈回，玩家才看得出來是「多了幾局」
        if (awarded > 0) AppAnimation.playBounce(counterNode, { ...FG_RETRIGGER_BOUNCE });
    }

    // 進出 FG 模式 覆寫
    /**
     * 依主遊戲／免費遊戲切換底部列的樣式。
     *
     * @param gameMode 目前的遊戲狀態。
     */
    setGameMode(gameMode: GameStateKey): void {
        let isFg = gameMode === GameStateKey.FG;
        this.setFgCounterVisible(isFg);
        if (isFg) {
            this.setSpinArrowStatus(false);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(true);
        }
    }

    /**
     * 更新玩家餘額顯示，格式依目前幣別決定。
     *
     * @param balance 餘額。
     */
    updateUserBalance(balance) {
        let userBalance = this.userFrame.node.getChildByName('UserBalance').getComponent(Label);
        userBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    /**
     * 更新本局贏分顯示，格式依目前幣別決定。
     *
     * @param balance 贏分。
     */
    updateWinBalance(balance) {

        let winBalance = this.winFrame.node.getChildByName('WinBalance').getComponent(Label);
        winBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    /**
     * 更新下注額顯示，格式依目前幣別決定。
     *
     * @param balance 下注額。
     */
    updateBetBalance(balance) {
        let betBalance = this.betFrame.node.getChildByName('BetBalance').getComponent(Label);
        betBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    // ******************** 更新 UI  ************************
    /**
     * 換加速鈕的圖；節點已經銷毀或沒給圖就直接返回。
     *
     * @param spriteFrame 新的圖；falsy 時不動。
     */
    async setTurboBtnImage(spriteFrame) {
        if (!spriteFrame || !this.turboBtn?.node?.isValid) return;
        try {
            this.turboBtn.node.getComponent(Sprite).spriteFrame = spriteFrame;
        } catch (e) {
            console.warn('[TemplateView] setTurboBtnImage failed', e);
        }
    }
    /**
     * 設定減注鈕是否要變灰。
     *
     * @param status true 代表**不可按**（已經在最低注）。
     */
    setMinusBtnStatus(status: boolean) {
        this.minusBtn.interactable = !status;
    }
    /**
     * 設定加注鈕是否要變灰。
     *
     * @param status true 代表**不可按**（已經在最高注）。
     */
    setAddBtnStatus(status: boolean) {
        this.plusBtn.interactable = !status;
    }
    // ******************** 設定狀態  ************************
    /**
     * 顯示或隱藏 spin 鈕上的箭頭。
     *
     * @param status 要不要顯示。
     */
    setSpinArrowStatus(status: boolean) {
        this.spinArrowSprite.active = status;
    }

    /**
     * 顯示或隱藏 spin 鈕上的停止圖示。
     *
     * @param status 要不要顯示。
     */
    setSpinStopStatus(status: boolean) {
        this.spinStopSprite.active = status;
    }

    /**
     * 顯示或隱藏 spin 那一區。
     *
     * @param status 要不要顯示。
     */
    setSpinFrameVisible(status: boolean) {
        this.spinFrame.node.active = status;
    }
    /**
     * 顯示或隱藏下注那一區。
     *
     * @param status 要不要顯示。
     */
    setBetFrameVisible(status: boolean) {
        this.betFrame.node.active = status;
    }
    /**
     * 切換自動轉的「無限」標記與剩餘次數數字，兩者互斥。
     *
     * @param status true 顯示無限標記，false 顯示次數。
     */
    setInfiniteVisible(status: boolean) {
        this.autoSpinStatus.getChildByName('Infinite').active = status;
        this.autoSpinStatus.getChildByName('AutoTimes').active = !status;
    }

    /**
     * 顯示或隱藏免費局剩餘次數。顯示時會讓出自動次數的位置。
     *
     * @param status 要不要顯示。
     */
    setFgCounterVisible(status: boolean) {
        if (this.FGCounter) this.FGCounter.active = status;

        const autoTimes = this.autoSpinStatus?.getChildByName('AutoTimes');
        const infinite = this.autoSpinStatus?.getChildByName('Infinite');
        if (autoTimes) autoTimes.active = !status && !infinite?.active;
    }
    /**
     * 寫入畫面角落的版本字串。
     *
     * @param version 版本字串。
     */
    setVersionLabel(version: string) {
        this.versionLabel.string = version;
    }
    /**
     * 顯示或隱藏自動轉的狀態區。
     *
     * @param status 要不要顯示。
     */
    setAutoSpinStatus(status: boolean) {
        this.autoSpinStatus.active = status;
    }

    /**
     * 回到一般可操作的樣式：兩區都顯示、箭頭復位、停止與自動的樣式全部關掉。
     */
    setDefaultMode() {
        //Layout
        this.setSpinFrameVisible(true);
        this.setBetFrameVisible(true);
        //個別按鈕
        this.setSpinArrowStatus(true);
        this.resumeSpinAction();
        this.setSpinStopStatus(false);
        this.setAutoSpinStatus(false);
        this.setInfiniteVisible(false);
        this.stopAutoSpinAction();
    }

    /** 切回一般 spin 狀態：箭頭轉一圈後顯示箭頭、關掉停止與自動的樣式。 */
    setSpinMode() {
        //Layout
        this.setSpinFrameVisible(true);
        this.setBetFrameVisible(true);
        this._playSpinAction(() => {
            //個別按鈕
            this.setSpinArrowStatus(true);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(false);
            this.setInfiniteVisible(false);
        });
    }

    /**
     * 切到自動 spin 狀態。
     *
     * @param times 剩餘次數；不給或給無限標記時顯示無限樣式。
     */
    setAutoSpinMode(times?: number | string) {
        this._playSpinAction(() => {
            this.playAutoSpinAction(times);
            //Layout
            this.setSpinFrameVisible(true);
            this.setBetFrameVisible(true);
            //個別按鈕
            this.setSpinArrowStatus(false);
            this.setSpinStopStatus(false);
            this.setAutoSpinStatus(true);
        }, true);
    }

    /**
     * 免費遊戲樣式：spin 與下注兩區都收起來，玩家不能操作。
     */
    setFeatureMode() {
        //Layout
        this.setSpinFrameVisible(false);
        this.setBetFrameVisible(false);
    }

    //spin 動畫
    /**
     * 播 spin 箭頭轉一圈並淡出的動效；已經有動效在跑時直接呼叫回呼。
     *
     * @param callBack 轉圈接近尾聲（0.9 秒）時呼叫，不是整段結束才呼叫——
     *         讓後續的狀態切換跟淡出重疊，看起來比較連貫。
     */
    playSpinAction(callBack?: Function) {
        if (this.spinTween) {
            if (callBack) callBack();
            return;
        }

        const uiOpacity = this.spinArrowSprite.getComponent(UIOpacity) || this.spinArrowSprite.addComponent(UIOpacity);

        const spinOnce = tween().to(1, { eulerAngles: new Vec3(0, 0, -360) }, { easing: 'backIn' }).call(() => this.setSpinArrowStatus(false));
        const fadeOut = tween(uiOpacity).delay(0.8).to(0.2, { opacity: 0 }, { easing: 'sineOut' });
        // 0.9 秒就回呼、不等整段跑完，讓後續的狀態切換跟淡出重疊
        const notify = tween().delay(0.9).call(() => callBack?.());

        this.spinTween = tween(this.spinArrowSprite).parallel(spinOnce, fadeOut, notify).start();
    }
    /**
     * 中止 spin 箭頭的動效並把角度與透明度復位。
     */
    resumeSpinAction() {
        if (this.spinTween) {
            this.spinTween.stop();
            this.spinTween = null;
        }
        this.spinArrowSprite.eulerAngles = new Vec3(0, 0, 0);
        let uiOpacity = this.spinArrowSprite.getComponent(UIOpacity) || this.spinArrowSprite.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
    }

    /**
     * 播自動模式的按鈕動效。
     *
     * @param _speed 保留參數，這一支沒有用到。
     * @returns 動效準備好之後 resolve。
     */
    async playAutoSpinAction(_speed?): Promise<void> {
        this.autoArrowSprite.active = true;
        (await this._ensurePauseIcon()).active = true;
    }
    /**
     * 停掉自動模式的按鈕動效並還原成一般樣式。
     *
     * @returns 還原完成後 resolve。
     */
    async stopAutoSpinAction() {
        if (this._pauseIcon?.isValid) this._pauseIcon.active = false;
        this.autoArrowSprite.active = false;
    }
    /**
     * 切換操作鎖遮罩。
     *
     * @param islock true 時蓋上遮罩擋住所有按鈕。
     */
    setLockStatus(islock) {
        this.lockView.node.active = islock;
    }
    // spin 鈕在各狀態下要換的圖。目前唯一的使用者 setSpinBtnSprite() 只被下面兩支
    // 註解掉的覆寫（setDefaultMode／setFeatureMode）呼叫，等 #9 換皮決定要不要用這套
    // 換圖做法時再一起處理；在那之前欄位留著，prefab 上的值也不要清掉。
    @property(SpriteFrame)
    spinBtnDefaultSprite: SpriteFrame = null!;

    @property(SpriteFrame)
    spinBtnSpinningSprite: SpriteFrame = null!;

    @property(SpriteFrame)
    spinBtnAutoSprite: SpriteFrame = null!;

    @property(SpriteFrame)
    spinBtnFeatureSprite: SpriteFrame = null!;

    private FGCounter: Node | null = null;
    /** 抓 spin 鈕底下的 FG 計數節點，只抓一次。 */
    init() {
        if (!this.FGCounter) this.FGCounter = this.spinBtn.node.getChildByName('FGCounter');
    }

    /**
     * 換掉 spin 鈕中央的圖示。
     *
     * @param frame 新圖；null 時不動。
     */
    private setSpinBtnSprite(frame: SpriteFrame | null): void {
        if (!frame) return;
        const sprite = this.spinArrowSprite?.getComponent(Sprite);
        if (sprite) sprite.spriteFrame = frame;
    }

    /**
     * 播 spin 箭頭轉圈的共用動效；已經有動效在跑時直接呼叫回呼、不疊第二份。
     *
     * @param callBack 轉圈告一段落後呼叫。
     * @param fadeOpacity 是否在轉圈尾聲把箭頭淡出，setAutoSpinMode() 需要。
     */
    private _playSpinAction(callBack?: () => void, fadeOpacity: boolean = false) {
        if (this.spinTween) {
            callBack?.();
            return;
        }
        this.spinTween = AppAnimation.playSpinArrow(this.spinArrowSprite, { fadeOpacity }, callBack);
    }

    // autoSpin pause 圖示
    private _pauseIcon: Node | null = null;
    private _pauseIconSpriteFrame: SpriteFrame | null = null;

    /**
     * 取得（必要時先建立）自動模式下的暫停圖示節點。
     *
     * @returns 暫停圖示節點。
     */
    private async _ensurePauseIcon(): Promise<Node> {
        if (this._pauseIcon?.isValid) return this._pauseIcon;
        const n = new Node('pauseIcon');
        this._pauseIcon = n;
        n.layer = this.autoArrowSprite.layer;
        this.autoArrowSprite.parent.addChild(n);
        n.addComponent(Sprite).spriteFrame = this._pauseIconSpriteFrame ?? (await this.assetBundle.getSpriteFrame('main_btn_pause'));
        return n;
    }
}
