import { _decorator, Component } from 'cc';
import { SubscriptionBag } from './SubscriptionBag';
import type { TypedEventBus } from './TypedEventBus';

const { ccclass } = _decorator;

/**
 * EventComponent
 *
 * MobxObserver 的原生替代基底類別，移除 mobx 依賴。
 *
 * 差異：MobxObserver 是「訂閱一個運算式，值變動時自動重跑 effect」（依賴追蹤），
 * EventComponent 改成「明確訂閱某個具名事件」，沒有魔法依賴追蹤——
 * 這比較貼近 SGEngine／EventBus 的設計哲學：資料變動時由 Store 自己
 * emit 明確的事件（例如 GAME_EVENT_TYPE.USER_BALANCE_CHANGED），
 * 而不是讓框架去猜哪些運算式需要重新執行。
 *
 * 遷移方式範例：
 *   舊：this.registerReaction(() => store.balance, (v) => label.string = String(v));
 *   新：this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.USER_BALANCE_CHANGED,
 *          (e) => label.string = String(e.balance));
 */
@ccclass('1003/EventComponent')
export class EventComponent extends Component {
    protected readonly subscriptions = new SubscriptionBag();

    /**
     * 訂閱一個 TypedEventBus 事件，並自動在 onDestroy 時解除。
     * 回傳 disposer，需要提前解除訂閱時可自行呼叫。
     */
    protected subscribeEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): () => void {
        return this.subscriptions.add(bus.on(type, handler));
    }

    /** 加入任意 disposer（例如 Cocos node.on 的解除函式），統一交給 subscriptions 管理生命週期 */
    protected trackDisposer(disposer: () => void): () => void {
        return this.subscriptions.add(disposer);
    }

    /**
     * 元件銷毀時把所有訂閱一次解除。
     *
     * 這是整套訂閱機制的收尾點：子類別覆寫 onDestroy() 時務必呼叫 super，
     * 否則事件會繼續打到已銷毀的節點上。
     */
    public override onDestroy(): void {
        this.subscriptions.dispose();
    }
}
