import {
    GAME_EVENT_ID,
    GAME_EVENT_TYPE,
    gameRuntimeEventBus,
} from "../../events/GameRuntimeEventBus";

export default class LoadingModel {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/LoadingStore') */
    public readonly $modelType = 'store/LoadingStore';

    private _progress = 0;
    /**
     * 載入進度（0～1）。
     *
     * @returns 進度。
     */
    get progress(): number { return this._progress; }
    /**
     * 更新載入進度並發 LOADING_PROGRESS_CHANGED；跟目前相同時直接略過。
     *
     * @param progress 進度（0～1）。
     */
    setProgress(progress: number): void {
        if (this._progress === progress) return;
        this._progress = progress;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.LOADING_PROGRESS_CHANGED, {
            eventId: GAME_EVENT_ID.LOADING_PROGRESS_CHANGED,
            progress,
        });
    }

    /** 保留建構子參數是為了相容 LoadingViewModel 裡 `new LoadingModel({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}
}
