import { Asset, assetManager, AssetManager, AudioClip, Prefab, SpriteFrame } from 'cc';

/**
 * AppAssetBundle
 * 原生替代 KYCocosSDK/Module/KYAssetBundle.ts，方法簽名 1:1 對應，
 * 供逐步替換 import 路徑使用，KYCocosSDK 內檔案本身不受影響。
 */
export default class AppAssetBundle {
    private static instanceMap = {};
    private readonly _bundleName: string;
    private _imageRootPath: string = '';
    private callBackFun: (completedCount: number, totalCount: number, item: Asset) => void = null;
    totalLoadcount: number = 0;
    loadcount: number = 0;
    resourceMap: Record<string, SpriteFrame> = {};
    /**
     * 取得指定 bundle 的包裝物件，第一次呼叫時才建立。
     *
     * @param bundleName bundle 名稱。
     * @returns 對應的實例。
     */
    public static getInstance(bundleName: string): AppAssetBundle {
        if (!AppAssetBundle.instanceMap[bundleName]) {
            let assetBundle = new AppAssetBundle(bundleName);
            AppAssetBundle.instanceMap[bundleName] = assetBundle;
        }
        return AppAssetBundle.instanceMap[bundleName];
    }

    /**
     * 私有建構子，一律走 getInstance() 取得實例。
     *
     * @param bundleName 這個實例負責的 bundle。
     */
    private constructor(bundleName) {
        this._bundleName = bundleName;
    }
    /**
     * 取得已載入的 bundle，還沒載就先載。
     *
     * @returns Cocos 的 bundle 物件。
     */
    async getBundle(): Promise<AssetManager.Bundle> {
        return await this.loadBundle();
    }
    /** 本次 session 是否已經載入過 用來判斷還要不要做版本檢查 */
    public hasCachedBundle(): boolean {
        return !!assetManager.getBundle(this._bundleName);
    }
    /**
     * 設定圖片的根路徑，之後 preloadImages()／getSpriteFrame() 都以它為前綴。
     *
     * @param rootPath 相對於 bundle 的資料夾路徑。
     */
    public setImageRootPath(rootPath: string) {
        this._imageRootPath = rootPath;
    }
    /**
     * remoteUrl 帶完整網址時（例如版本化的熱更資料夾）直接從那個網址載入
     * 不帶時走一般註冊過的 bundle 名稱／預設位置 載入回來的 bundle 名稱
     * 是由下載回來的 config.json 內容自己的 name 欄位決定 跟載入時用網址
     * 還是用名稱無關 所以 assetManager.getBundle(this._bundleName) 這種
     * 用法不受影響
     */
    public async loadBundle(remoteUrl?: string): Promise<AssetManager.Bundle> {
        return new Promise(async (resolve, reject) => {
            // 檢查是否已經載入過了 (有快取就直接回傳)
            let bundle = assetManager.getBundle(this._bundleName);
            if (bundle) {
                resolve(bundle);
                return;
            }
            const onLoaded = (err: Error | null, bundle: AssetManager.Bundle) => {
                if (err) reject(err);
                else resolve(bundle);
            };
            if (remoteUrl) {
                // downloader 內部固定用 `${url}/config.json` 組網址 尾巴帶斜線會變成雙斜線
                // packageUrl 慣例上結尾一定帶斜線（原生 manifest 那邊需要）這裡單獨處理掉
                const url = remoteUrl.endsWith('/') ? remoteUrl.slice(0, -1) : remoteUrl;
                assetManager.loadBundle(url, onLoaded);
            } else {
                assetManager.loadBundle(this._bundleName, onLoaded);
            }
        });
    }

    /**
     * 載入單一資源的共用實作：先確保 bundle 在手上，再走 bundle.load()。
     *
     * 注意 `bundle.load()` 的 callback 在分頁真的 hidden 時不會被觸發——
     * 畫面看起來一切正常但這個 promise 永遠不會 settle（見 agent-pitfalls.md 坑 #32）。
     *
     * @param path 相對於 bundle 的資源路徑。
     * @param type 資源型別。
     * @param progress 進度回呼。
     * @returns 載入完成後帶回資源。
     * @throws 資源不存在或載入失敗時 reject。
     */
    private async _load(path: string, type: any, progress?) {
        const bundle: AssetManager.Bundle = await this.loadBundle();

        // 只有 callback API 這一層需要手動包 Promise，bundle 本身用 await 取即可
        return new Promise((resolve, reject) => {
            bundle.load(path, type, progress, (err, asset) => {
                if (err) reject(err);
                else resolve(asset);
            });
        });
    }

    /**
     * 把圖片根路徑底下的 SpriteFrame 整個資料夾載進來並建立名稱索引。
     *
     * @param path 接在圖片根路徑後面的子資料夾，預設整包。
     * @returns 名稱對應 SpriteFrame 的索引表。
     * @throws 資料夾載入失敗時 reject。
     */
    public async preloadImages(path = ''): Promise<Record<string, SpriteFrame>> {
        return new Promise(async (resolve, reject) => {
            const bundle = await this.getBundle();
            bundle.loadDir(this._imageRootPath + path, SpriteFrame, (err, assets) => {
                if (err) {
                    reject(err);
                    return;
                }
                assets.forEach((asset) => {
                    this.resourceMap[asset.name] = asset;
                });
                console.log('[AppAssetBundle] 所有圖片預載完成，數量:', assets.length);
                resolve(this.resourceMap);
            });
        });
    }
    /**
     * 背景預載一支 prefab，不等結果也不處理錯誤——純粹是讓之後真的要用時比較快。
     *
     * @param path 相對於 bundle 的 prefab 路徑。
     * @param progress 進度回呼。
     */
    public async preLoadPrefab(path: string, progress?) {
        let bundle = await this.getBundle();
        bundle.preload(path, Prefab, progress, (err) => {
            return;
        });
    }
    /**
     * 載入一支 prefab。
     *
     * @param path 相對於 bundle 的 prefab 路徑。
     * @param progress 進度回呼。
     * @returns prefab 資源。
     * @throws prefab 不存在或載入失敗時 reject。
     */
    public async loadPrefab(path: string, progress?): Promise<Prefab> {
        return new Promise(async (resolve, reject) => {
            this._load(path, Prefab, progress)
                .then((asset: Prefab) => {
                    resolve(asset);
                })
                .catch((err) => {
                    reject(err);
                });
        });
    }

    /**
     * 載入一支音檔。
     *
     * @param path 相對於 bundle 的音檔路徑。
     * @param progress 進度回呼。
     * @returns 音檔資源。
     * @throws 音檔不存在或載入失敗時 reject。
     */
    public async loadAudioClip(path: string, progress?): Promise<AudioClip> {
        return new Promise(async (resolve, reject) => {
            this._load(path, AudioClip, progress)
                .then((asset: AudioClip) => {
                    resolve(asset);
                })
                .catch((err) => {
                    reject(err);
                });
        });
    }

    public async loadAsset<T extends Asset>(path: string, type: new () => T, progress?): Promise<T> {
        return this._load(path, type, progress) as Promise<T>;
    }
    /**
     * 依**名稱**（不是路徑）取一張圖，會先查 preloadImages() 建好的索引。
     *
     * 這種「用字面字串找資產」的取法不在 import 圖也不在 uuid 圖上，
     * 搬 bundle 時靜態分析抓不到，要另外 grep 比對（見 agent-pitfalls.md 坑 #26）。
     *
     * @param path SpriteFrame 的名稱。
     * @returns 對應的 SpriteFrame；索引裡沒有時是 undefined。
     * @throws 資料夾載入失敗時 reject。
     */
    async getSpriteFrame(path: string): Promise<SpriteFrame> {
        if (this.resourceMap[path]) return this.resourceMap[path] as SpriteFrame;
        return new Promise(async (resolve, reject) => {
            const bundle = await this.getBundle();
            bundle.loadDir(this._imageRootPath, SpriteFrame, (err, assets) => {
                if (err) reject(err);
                else resolve(assets.find((a) => a.name === path));
            });
        });
    }

    /**
     * 批次預載多支 prefab，每支各自反查它屬於哪個 bundle。
     *
     * @param paths prefab 路徑清單。
     * @param progress 進度回呼。
     * @returns 全部載完之後 resolve。
     */
    public async preloadPrefabs(paths: string[], progress?) {
        console.log('[AppAssetBundle] preloadPrefabs, paths: ', paths);
        let loadList = [];
        for (const path of paths) {
            let name = await this.getInfoWithPath(path);
            if (name) {
                loadList.push(() => AppAssetBundle.instanceMap[name].loadPrefab(path, progress));
            }
        }
        console.log('[AppAssetBundle] 需要載入的 bundle 列表:', loadList);
        await Promise.all(loadList.map((fn) => fn()));
        console.log('[AppAssetBundle] 所有 prefab 載入完成');
    }

    /**
     * 在所有已建立的 bundle 裡反查某個路徑屬於誰。
     *
     * @param path 資源路徑。
     * @returns 找到的 bundle 名稱；都找不到時是 undefined。
     */
    async getInfoWithPath(path: string) {
        for (const bundleName of Object.keys(AppAssetBundle.instanceMap)) {
            const bundle = await AppAssetBundle.instanceMap[bundleName].getBundle();
            let info = await bundle.getInfoWithPath(path);

            if (info) {
                console.log('[AppAssetBundle] 找到 bundle:', bundleName);
                return bundleName;
            }
        }
        console.error('❌ 找不到對應的 bundle:', path);
        return null;
    }
}
