import { _decorator, Component, Node, Sprite, UIOpacity, UITransform, Vec3, sp } from 'cc';
import { trySetAnimation, tryClearAnimation } from '../../utils/SpineSafe';
import AppAnimation from '../../ui/AppAnimation';

const { ccclass, property } = _decorator;

/**
 * 單一符號格的顯示元件：靜態圖、中獎／消除特效與 scatter 的演出。
 *
 * 符號本身（h／l／scatter／wild）的演出有兩種模式，由 {@link NgSymbol.useSpine} 切換：
 * - **Sprite 模式（預設）**：中獎時拿靜態圖做「放大再縮回」的 tween，scatter 中獎時循環縮放。
 *   1003 自己的符號 spine 還沒到位，prefab 上的 symbol_h／symbol_l／symbol_scatter 是 1001
 *   荷魯斯的美術，播出來圖會不對。
 * - **Spine 模式**：播 symbol_h／symbol_l／symbol_scatter，這條路徑原封保留，素材到位後勾起來即可。
 *
 * 不帶符號圖的通用特效兩種模式都一樣：中獎的 symbol_win 火焰框、消除的 symbol_frame 爆破。
 *
 * 1001 繼承來的倍率球（symbol_m／symbol_m_fx／symbol_up）、Jackpot（symbol_jp、JP 徽章）
 * 與 coin 金額顯示，已於 2026-09-14 依 GDD 連同 prefab 節點一起移除。
 */
@ccclass('1003/NgSymbol')
export class NgSymbol extends Component {
    @property({ tooltip: '符號橫向拉伸倍率（1=正方形，>1 稍寬長方形）。套在 visual 容器上，不受落地 squash 與各種重置影響' })
    stretchX: number = 1;

    @property({
        tooltip:
            '勾選＝中獎／scatter 播符號 spine（symbol_h／symbol_l／symbol_scatter）；不勾＝用靜態圖做縮放 tween。1003 自己的符號 spine 到位前維持不勾'
    })
    useSpine: boolean = false;

    @property({ tooltip: '靜態圖中獎彈跳的放大倍率（Sprite 模式）' })
    winPulseScale: number = 1.15;

    @property({ tooltip: '靜態圖中獎彈跳的放大時長（秒，1 倍速；Sprite 模式）' })
    winPulseUp: number = 0.3;

    @property({ tooltip: '靜態圖中獎彈跳的縮回時長（秒，1 倍速；Sprite 模式）' })
    winPulseDown: number = 0.3;

    /** DebugPanel「Symbol 縮放」用的整體縮放倍率，套在 visual 容器上（跟 stretchX 是同一個節點，
     *  不受落地 squash／各種 setScale(1,1,1) 重置影響）。預設 1：顯示大小照 prefab 設計的格子尺寸 */
    private scaleMultiplier: number = 1;

    /** symbol_frame 缺 skeletonData 的警告只印一次：每次消除每一格都會問 hasEliminateFx，逐格印會洗版 */
    private static warnedMissingFrameData = false;

    /** spriteFrame 節點在 prefab 上設的 scale（目前 0.25）。中獎彈跳以它為基準放大，結束時還原成它 */
    private readonly spriteBaseScale = new Vec3(1, 1, 1);

    private visual: Node = null!;
    private symbolWin: sp.Skeleton = null!;
    private symbolH: sp.Skeleton = null!;
    private symbolL: sp.Skeleton = null!;
    private symbolScatter: sp.Skeleton = null!;
    private symbolFrame: sp.Skeleton = null!;
    private spriteFrameNode: Node = null!;

    /** 抓齊各層 spine 與顯示元件，先全部關掉，等實際要用時才打開。 */
    protected override onLoad(): void {
        const v = this.buildVisualWrapper();
        this.symbolH = v.getChildByName('symbol_h')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolH) this.symbolH.node.active = false;

        this.symbolWin = v.getChildByName('symbol_win')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolWin) this.symbolWin.node.active = false;

        this.symbolL = v.getChildByName('symbol_l')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolL) this.symbolL.node.active = false;

        this.spriteFrameNode = v.getChildByName('spriteFrame') ?? null!;
        if (this.spriteFrameNode) this.spriteBaseScale.set(this.spriteFrameNode.scale);

        this.symbolScatter = v.getChildByName('symbol_scatter')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolScatter) {
            tryClearAnimation(this.symbolScatter, 'NgSymbol.symbol_scatter');
            this.symbolScatter.node.active = false;
        }

        this.symbolFrame = v.getChildByName('symbol_frame')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolFrame) {
            tryClearAnimation(this.symbolFrame, 'NgSymbol.symbol_frame');
            this.symbolFrame.node.active = false;
        }
    }

    /**
     * 把既有子節點搬進一個叫 visual 的容器，之後縮放只改這一層。
     *
     * visual 要補一個跟根節點同尺寸、同 anchor 的 UITransform：子節點上的 Widget
     * （例如 spriteFrame 的水平置中＋靠下）是對父節點對齊的，父節點沒有 UITransform 時
     * Widget 會當成 0×0 來算，符號整個偏掉而且不報錯。
     *
     * @returns 建好的 visual 節點。
     */
    private buildVisualWrapper(): Node {
        const visual = new Node('visual');
        const rootUi = this.node.getComponent(UITransform);
        if (rootUi) {
            const visualUi = visual.addComponent(UITransform);
            visualUi.setContentSize(rootUi.contentSize);
            visualUi.setAnchorPoint(rootUi.anchorPoint);
        }
        const children = [...this.node.children];
        this.node.addChild(visual);
        for (const c of children) c.setParent(visual);
        this.visual = visual;
        this.applyVisualScale();
        return visual;
    }

    /** DebugPanel「Symbol 縮放」呼叫，即時套用不記錄；沿用 stretchX 同一個 visual 容器 */
    setScaleMultiplier(scale: number): void {
        this.scaleMultiplier = scale;
        this.applyVisualScale();
    }

    /** 把 stretchX 與縮放倍率套到 visual 容器上。 */
    private applyVisualScale(): void {
        this.visual?.setScale(this.stretchX * this.scaleMultiplier, this.scaleMultiplier, 1);
    }

    /**
     * 這一格有沒有 symbol_frame 消除特效可以播。
     *
     * 只看元件在不在不夠：prefab 上的 Skeleton Data 引用被清掉時元件還在，會走 spine 路線
     * 卻什麼都播不出來，符號在 133ms 憑空消失。所以連 skeletonData 一起檢查，沒有就回 false，
     * 讓 ReelView_1003.explode 退回 base 的縮小消除，並留一行 warn（整個 session 只印一次）。
     *
     * @returns 有 symbol_frame 且有 skeletonData 時為 true。
     */
    hasEliminateFx(): boolean {
        if (!this.symbolFrame) return false;
        if (this.symbolFrame.skeletonData) return true;
        if (!NgSymbol.warnedMissingFrameData) {
            NgSymbol.warnedMissingFrameData = true;
            console.warn(
                '[NgSymbol] symbol_frame 沒有 skeletonData，消除改用縮小 tween（檢查 NgSymbol_1003.prefab 的 Skeleton Data）'
            );
        }
        return false;
    }

    /** 消除爆破：播 symbol_frame，美術表規格＝動畫第 133ms 才關閉 symbol；播完整格轉透明、符號圖還原 active 供補格重用 */
    playEliminate(timeScale = 1): Promise<void> {
        if (!this.symbolFrame) return Promise.resolve();
        const hideSymbol = () => {
            if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = false;
        };
        this.scheduleOnce(hideSymbol, 0.133 / timeScale);
        return this.playSpineOnce(this.symbolFrame, 'animation', 1.2, timeScale).then(() => {
            this.unschedule(hideSymbol);
            const op = this.getComponent(UIOpacity);
            if (op) op.opacity = 0;
            if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = true;
        });
    }

    /**
     * scatter 落定時的顯示。Spine 模式打開 idle spine 並關掉靜態圖避免疊影；
     * Sprite 模式下 scatter 就是靜態圖本身，不另外演出。
     */
    showScatter(): void {
        if (!this.useSpine) return;
        if (!this.symbolScatter) return;
        this.symbolScatter.node.active = true;
        this.symbolScatter.timeScale = 1;
        trySetAnimation(this.symbolScatter, 'idle', true, 'NgSymbol.showScatter');
        const spr = this.spriteFrameNode?.getComponent(Sprite); // 關上靜態避免動效重疊
        if (spr) spr.enabled = false;
    }

    /**
     * scatter 中獎演出（循環，直到 hideScatter）。Spine 模式播 win spine；
     * Sprite 模式讓靜態圖循環放大縮小。
     */
    playScatterWin(): void {
        if (!this.useSpine) {
            this.startSpritePulseLoop();
            return;
        }
        if (!this.symbolScatter) return;
        this.symbolScatter.node.active = true;
        this.symbolScatter.timeScale = 1;
        trySetAnimation(this.symbolScatter, 'win', true, 'NgSymbol.playScatterWin');
        const spr = this.spriteFrameNode?.getComponent(Sprite);
        if (spr) spr.enabled = false;
    }

    /**
     * 結束 scatter 演出並還原靜態圖：關掉 scatter spine、停掉靜態圖的縮放 tween。
     *
     * 換符號（ReelView_1003.setSymbolDisplay）時一律會呼叫，所以兩種模式的殘留都在這裡清。
     */
    hideScatter(): void {
        if (this.symbolScatter) this.symbolScatter.node.active = false;
        this.stopSpritePulse();
        const spr = this.spriteFrameNode?.getComponent(Sprite); // 還原靜態圖
        if (spr) spr.enabled = true;
    }

    /**
     * 中獎演出：symbol_win 火焰框，加上符號本身的演出（依 useSpine 決定是 spine 還是靜態圖彈跳）。
     *
     * @param frameName 目前符號的圖名，Spine 模式用它挑 symbol_h／symbol_l 的動畫。
     * @param timeScale 隨三段速的 winFx 時長縮放（同 playEliminate 的做法），1 = 原速。
     * @returns 全部演出結束後 resolve。
     */
    playWin(frameName?: string, timeScale = 1): Promise<void> {
        const tasks: Promise<void>[] = [this.playSpineOnce(this.symbolWin, 'animation', 1.6, timeScale)];
        if (!this.useSpine) {
            tasks.push(this.playSpritePulse(timeScale));
        } else {
            if (frameName && this.symbolL && frameName.startsWith('symbol_l')) {
                tasks.push(this.playSymbolAnimation(this.symbolL, frameName, timeScale));
            }
            if (frameName && this.symbolH && frameName.startsWith('symbol_h')) {
                tasks.push(this.playSymbolAnimation(this.symbolH, frameName, timeScale));
            }
        }
        return Promise.all(tasks).then(() => undefined);
    }

    /**
     * Sprite 模式的中獎演出：靜態圖放大再縮回一次。
     *
     * tween 可能被別處停掉（換符號時的 hideScatter），那樣 onComplete 就永遠不會來，
     * 等著它的 playWinFx 跟著吊死（agent-pitfalls.md 坑 #34）——所以另外排一個計時保底。
     *
     * @param timeScale 播放倍率，時長會除以它。
     * @returns 彈跳結束（或保底時間到）後 resolve；沒有靜態圖節點時立即 resolve。
     */
    private playSpritePulse(timeScale: number): Promise<void> {
        const node = this.spriteFrameNode;
        if (!node?.isValid) return Promise.resolve();
        return new Promise<void>((resolve) => {
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                this.unschedule(finish);
                resolve();
            };
            const up = this.winPulseUp / timeScale;
            const down = this.winPulseDown / timeScale;
            node.setScale(this.spriteBaseScale);
            AppAnimation.playBounce(
                node,
                { scaleMultiplier: this.winPulseScale, durationUp: up, durationDown: down },
                finish
            );
            this.scheduleOnce(finish, up + down + 0.1);
        });
    }

    /** Sprite 模式的 scatter 中獎演出：靜態圖循環放大縮小，直到 hideScatter 停掉。 */
    private startSpritePulseLoop(): void {
        const node = this.spriteFrameNode;
        if (!node?.isValid) return;
        node.setScale(this.spriteBaseScale);
        AppAnimation.playScaleBreath(node, {
            scaleMultiplier: this.winPulseScale,
            durationUp: this.winPulseUp,
            durationDown: this.winPulseDown
        });
    }

    /** 停掉靜態圖上的縮放 tween，scale 還原成 prefab 上的值。 */
    private stopSpritePulse(): void {
        const node = this.spriteFrameNode;
        if (!node?.isValid) return;
        AppAnimation.stopScaleBreath(node);
        node.setScale(this.spriteBaseScale);
    }

    /**
     * 播一次指定的 spine 動畫並等它結束。
     *
     * @param sk 目標 spine。
     * @param anim 動畫名稱。
     * @param timeScale 播放倍率，預設 1。
     * @returns 播完後 resolve；動畫不存在時立即 resolve。
     */
    private playSymbolAnimation(sk: sp.Skeleton, anim: string, timeScale = 1): Promise<void> {
        return new Promise<void>((resolve) => {
            if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = false;
            sk.node.active = true;
            sk.timeScale = timeScale;
            const entry = sk.setAnimation(0, anim, false);
            const dur = ((entry?.animation?.duration ?? 1.5) + 0.2) / timeScale;
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                sk.setCompleteListener(null);
                if (sk.node?.isValid) sk.node.active = false;
                if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = true;
                resolve();
            };
            sk.setCompleteListener((e) => {
                if (e.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, dur);
        });
    }

    /** 播一次性 spine 動畫,播完隱藏節點。loop=false 時 Cocos complete 不一定觸發,用 timeout 保底 */
    private playSpineOnce(sk: sp.Skeleton, anim: string, fallback: number, timeScale = 1): Promise<void> {
        return new Promise<void>((resolve) => {
            if (!sk) {
                resolve();
                return;
            }
            sk.node.active = true;
            sk.timeScale = timeScale;
            sk.setAnimation(0, anim, false);
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                sk.setCompleteListener(null);
                if (sk.node?.isValid) sk.node.active = false;
                resolve();
            };
            sk.setCompleteListener((entry) => {
                if (entry.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, fallback / timeScale);
        });
    }
}
