import { _decorator, Layout, Node, ProgressBar } from 'cc';
import LoadingViewModel from './LoadingViewModel';
import { EventComponent } from '../../events/EventComponent';
import type { TypedEventBus } from '../../events/TypedEventBus';

const { ccclass, property } = _decorator;

@ccclass('1003/LoadingView')
export class LoadingView extends EventComponent {
    /** EventComponent.subscribeEvent 是 protected，這裡轉一層 public 供 LoadingViewModel 呼叫 */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(ProgressBar)
    progressBar: ProgressBar = null;

    @property(Node)
    tipH: Node = null;
    @property(Node)
    tipV: Node = null;

    viewModel: LoadingViewModel;

    isPortrait: boolean;
    verticalY = { logo: -630, progressBar: -585 };
    horizontalY = { logo: -320, progressBar: -265 };
    /** 目前不需要做事，只把基底的 onLoad 接起來。 */
    protected override onLoad(): void {
        super.onLoad?.();
    }
    /**
     * 建立這個畫面的 ViewModel。
     */
    protected override start(): void {
        this.viewModel = new LoadingViewModel(this);
    }
    /**
     * 更新進度條。
     *
     * @param count 進度（0～1）。
     */
    public updateProgress(count: number) {
        this.progressBar.progress = count;
    }
    /**
     * 依方向切換橫版／直版的提示文字。
     *
     * @param isPortrait 方向字串，'portrait' 代表直版。
     */
    checkPosition(isPortrait) {
        if (isPortrait !== 'portrait') {
            this.tipH.active = true;
            this.tipV.active = false;
            return;
        }
        this.tipH.active = false;
        this.tipV.active = true;
    }
}
