// ============================================================
// engines/types.ts
// 每款遊戲的假資料「玩法引擎」介面。
//
// slot-api-mock.ts 只負責 WebSocket 攔截、餘額/歷史/獎池等傳輸與帳務，
// 真正決定盤面長相與中獎規則的部分由這個介面切開，讓玩法差異很大的遊戲
// （1001 的 pay-anywhere 消除 vs 1003 的 Ways 麻將）各自實作，
// 不必為了共用而把兩套規則塞進同一組 if。
// ============================================================

import type { SlotApiGameInfoResponse, SlotApiJackpotSpinResult, SlotApiRoundResult } from '../SlotApiTypes';

export interface MockRoundOutcome {
    roundResult: SlotApiRoundResult;
    totalWin: number;
    multiplier: number;
    actualJackpotCount: number;
}

export interface MockRoundEngine {
    /** Buy Feature 價格倍率；不支援的遊戲填 0 */
    readonly buyFeatureCostMul: number;

    /** currency 不在投注設定裡時回 null，由傳輸層回 ACK 失敗 */
    makeGameInfo(currency: string): SlotApiGameInfoResponse | null;

    /** 這局要塞幾顆 jackpot 符號；不支援 jackpot 的遊戲一律回 0 */
    decideJackpotSymbolCount(): number;

    makeJackpotResult(betAmount: string, count: number, currency: string): SlotApiJackpotSpinResult;

    makeRoundResult(betAmount: string, buyFeature: boolean, jackpotCount: number): MockRoundOutcome;
}
